// ---------------------------------------------------------------------------
// v90: pooled firmware-cached command objects.
//
// Native maps its firmware-consumed command objects cached (bit41 map option
// 0x20900000084 -> UAT attribute 0): ChannelState (AGXFirmwareResourceStack),
// TA/FRG/ConfigUpdate command pools (`PoolClass<..>::createBacking`) and the
// CommandBufferState/TSQ node backing. Those backings are created once and
// their elements are recycled; the firmware maintains its own copies with
// `__rtk_cache_clean_invalidate` (b100 28ad0) around each use (descriptor
// 0x2240 and node 0xc8 at the start path b2dc..b2f8 and at completion
// service), and native's unmap route issues only a TLBI (prepareFWUnmap)
// because the HAL200 ASC L2 invalidation it forwards to is a no-op.
//
// Linux therefore never unmaps these cached objects while firmware runs:
// when the owner is dropped (after the firmware-acknowledged teardown that
// already gates every owner drop) the whole owning mapping, backing and VA
// return to a bounded per-family pool and are reused, zeroed, by the next
// owner of the same family, like a native pool element. Pools are released
// only after the firmware is stopped (`g17p_fw_pool_release_all`). An
// object whose attribute change could not be proven is never reused and stays
// owned until a proven final firmware stop. Fresh allocations only; runtime diag bits
// 27..30 select families for A/B.
// ---------------------------------------------------------------------------

/// Family bits (diag knobs bits 27..30 >> 27).
pub(crate) const G17P_FW_FAMILY_DESCRIPTOR: u32 = 1;
pub(crate) const G17P_FW_FAMILY_TSQ_NODE: u32 = 2;
pub(crate) const G17P_FW_FAMILY_CHANNEL_STATE: u32 = 4;
pub(crate) const G17P_FW_FAMILY_CONFIG_UPDATE: u32 = 8;
const G17P_FW_POOL_POISON: u8 = 0x80;
const G17P_FW_POOL_SLOTS: usize = 64;
/// Bytes retained with the cached attribute; beyond this cap fresh objects stay
/// uncached (never an allocation failure).
const G17P_FW_POOL_CACHED_LIMIT: u64 = 128 * 1024 * 1024;

pub(crate) const fn g17p_fw_pool_index(family: u32) -> Option<usize> {
    match family {
        G17P_FW_FAMILY_DESCRIPTOR => Some(0),
        G17P_FW_FAMILY_TSQ_NODE => Some(1),
        G17P_FW_FAMILY_CHANNEL_STATE => Some(2),
        G17P_FW_FAMILY_CONFIG_UPDATE => Some(3),
        _ => None,
    }
}

/// Lock-free bounded pool of owned entries (raw `KBox` pointers). `put`
/// hands the entry back when every slot is occupied; `take` returns null
/// when empty. Each slot holds at most one entry; ownership moves with the
/// successful CAS/swap, so an entry is never shared or lost.
pub(crate) struct G17PFwPoolSlots<T, const N: usize> {
    slots: [core::sync::atomic::AtomicPtr<T>; N],
}

impl<T, const N: usize> G17PFwPoolSlots<T, N> {
    pub(crate) const fn new() -> Self {
        Self { slots: [const { core::sync::atomic::AtomicPtr::new(core::ptr::null_mut()) }; N] }
    }

    pub(crate) fn put(&self, entry: *mut T) -> core::result::Result<(), *mut T> {
        if entry.is_null() { return Err(entry); }
        for slot in &self.slots {
            if slot.compare_exchange(core::ptr::null_mut(), entry,
                Ordering::AcqRel, Ordering::Relaxed).is_ok() {
                return Ok(());
            }
        }
        Err(entry)
    }

    pub(crate) fn take(&self) -> *mut T {
        for slot in &self.slots {
            let entry = slot.swap(core::ptr::null_mut(), Ordering::AcqRel);
            if !entry.is_null() { return entry; }
        }
        core::ptr::null_mut()
    }
}

#[cfg(not(test))]
struct G17PPooledFwObject {
    mapping: Option<mmu::KernelMapping>,
    gem: Option<kernel::sync::aref::ARef<gem::Object>>,
    iova: u64,
    logical_size: usize,
    prefix: usize,
    cpu_wc: bool,
    family: u8,
}

#[cfg(not(test))]
kernel::sync::global_lock! {
    // SAFETY: initialized once in DriverModule::init before driver registration.
    unsafe(uninit) static G17P_FW_POOL_LOCK: Mutex<()> = ();
}

/// Called exactly once, before platform driver registration can create a UAT.
#[cfg(not(test))]
pub(crate) unsafe fn g17p_fw_pool_init() {
    // SAFETY: caller guarantees module initialization, before any pool access.
    unsafe { G17P_FW_POOL_LOCK.init() };
}

#[cfg(not(test))]
static G17P_FW_POOLS: [G17PFwPoolSlots<G17PPooledFwObject, G17P_FW_POOL_SLOTS>; 4] =
    [const { G17PFwPoolSlots::new() }; 4];
/// Reservations include active, pooled and poisoned entries. A cached object
/// always owns its return node and one slot of capacity before PTE mutation.
#[cfg(not(test))]
static G17P_FW_POOL_RESERVED: [AtomicU32; 4] = [const { AtomicU32::new(0) }; 4];
#[cfg(not(test))]
static G17P_FW_POOL_CACHED_BYTES: AtomicU64 = AtomicU64::new(0);
/// fresh, reused, returned, poisoned conversion counts.
#[cfg(not(test))]
static G17P_FW_POOL_STATS: [AtomicU32; 4] = [const { AtomicU32::new(0) }; 4];
#[cfg(not(test))]
fn g17p_fw_pool_stat(index: usize) -> u32 { G17P_FW_POOL_STATS[index].load(Ordering::Relaxed) }
#[cfg(not(test))]
fn g17p_fw_pool_bump(index: usize) { G17P_FW_POOL_STATS[index].fetch_add(1, Ordering::Relaxed); }

/// Pool transfers alone use this mutex, never submission or completion work.
/// No mapping destruction or allocation occurs while it is held.
#[cfg(not(test))]
impl Drop for MappedObject {
    fn drop(&mut self) {
        if self.fw_pool == 0 { return; }
        let mut entry = self.fw_node.take().expect("cached object owns return node");
        entry.family = self.fw_pool;
        self.fw_pool = 0;
        entry.mapping = self.mapping.take();
        entry.gem = Some(self.object.gem.clone());
        entry.iova = self.iova;
        let index = g17p_fw_pool_index(u32::from(entry.family & !G17P_FW_POOL_POISON))
            .expect("cached object owns family reservation");
        let guard = G17P_FW_POOL_LOCK.lock();
        if entry.mapping.as_ref().expect("cached owning mapping")
            .firmware_cache_owner().stopped() {
            G17P_FW_POOL_RESERVED[index].fetch_sub(1, Ordering::Relaxed);
            G17P_FW_POOL_CACHED_BYTES.fetch_sub(entry.logical_size as u64, Ordering::Relaxed);
            drop(guard);
            drop(entry);
            return;
        }
        // Every outstanding cached object reserves a slot, so a returning
        // object's slot capacity cannot be consumed by another allocation.
        G17P_FW_POOLS[index].put(KBox::into_raw(entry))
            .expect("reserved firmware pool capacity");
        g17p_fw_pool_bump(2);
    }
}

#[cfg(not(test))]
fn g17p_fw_pool_take(index: usize, uat: &mmu::Uat, size: usize,
                     prefix: usize, cpu_wc: bool) -> Option<MappedObject> {
    let guard = G17P_FW_POOL_LOCK.lock();
    for slot in &G17P_FW_POOLS.get(index)?.slots {
        let raw = slot.load(Ordering::Relaxed);
        if raw.is_null() { continue; }
        // SAFETY: all production slot ownership transfers hold the pool mutex.
        let entry = unsafe { &*raw };
        if entry.family & G17P_FW_POOL_POISON != 0 || entry.logical_size != size
            || entry.prefix != prefix || entry.cpu_wc != cpu_wc
            || !entry.mapping.as_ref()?.firmware_cache_owner().matches(uat) {
            continue;
        }
        slot.store(core::ptr::null_mut(), Ordering::Relaxed);
        // SAFETY: removed under the lock, exclusively owned by this caller.
        let mut entry = unsafe { KBox::from_raw(raw) };
        drop(guard);
        return Some(MappedObject {
            iova: entry.iova,
            object: gem::ObjectRef::new(entry.gem.take().expect("pooled GEM")),
            mapping: entry.mapping.take(),
            object_offset: 0,
            logical_size: entry.logical_size,
            cpu_wc: entry.cpu_wc,
            fw_pool: entry.family,
            fw_node: Some(entry),
        });
    }
    None
}

/// Bounded sweep: live foreign owners are never removed or restored. Stop
/// sets its witness before this lock; a returning object either publishes
/// before the sweep or observes the witness and frees outside the lock.
#[cfg(not(test))]
pub(crate) fn g17p_fw_pool_release_all() {
    let mut retired = [core::ptr::null_mut(); 4 * G17P_FW_POOL_SLOTS];
    let mut count = 0;
    {
        let _guard = G17P_FW_POOL_LOCK.lock();
        for (index, pool) in G17P_FW_POOLS.iter().enumerate() {
            for slot in &pool.slots {
                let raw = slot.load(Ordering::Relaxed);
                if raw.is_null() { continue; }
                // SAFETY: entries cannot move or be freed while locked.
                let entry = unsafe { &*raw };
                if !entry.mapping.as_ref().expect("pooled mapping")
                    .firmware_cache_owner().stopped() { continue; }
                slot.store(core::ptr::null_mut(), Ordering::Relaxed);
                G17P_FW_POOL_RESERVED[index].fetch_sub(1, Ordering::Relaxed);
                G17P_FW_POOL_CACHED_BYTES.fetch_sub(entry.logical_size as u64, Ordering::Relaxed);
                retired[count] = raw;
                count += 1;
            }
        }
    }
    for raw in &retired[..count] {
        // SAFETY: detached under the pool mutex, each pointer exclusively owned.
        drop(unsafe { KBox::from_raw(*raw) });
    }
}

#[cfg(not(test))]
/// RegionC TimerCSwitch configuration, applied after `encode_region_c` and
/// before firmware boot. RegionC+0 is native `AGXFirmware::setTimerCSwitch`
/// (kext 8880900) and +0x6a `setCSwitchTimerMultiplier` (889f4e4). B1 copies
/// both only at init or on notes 0x16/0x2a/0x2f (`3470`, gated by `177808`),
/// so a later store to the shared page has no effect. Every +0x6a-th 1 ms
/// engine walk (bundle+0xed0), each DM bit in +0 resumes that DM's installed
/// QIDs through group 3 (`23fc4..24020` -> `a2a8(3)`): a hardware
/// re-arbitration handshake plus re-add of any QID removed after an A==B park.
/// On an earlier driver line, without it a FRG queue parked under
/// multi-client contention was re-added only when the GPU drained, which Neo
/// measured as 2 s stalls and DEVICE_LOST; FRG with multiplier 16 passed
/// four-client qualification with no single-client cost, and multiplier 1
/// cost 23% light-render throughput. The native runtime TimerCSwitch value is
/// not established.
///
/// Both parameters now default to 0, which keeps the native encoded values
/// (+0 = 0, +0x6a = 1) and logs no override. On the iso2 line (2026-10-01)
/// the native encoding matched mask 2 / multiplier 16: depth-2 medians fell
/// inside each other's ranges, saturated runs were within noise, and the
/// original four-client FRG-stall reproducer ran 8 four-client and 2 mixed
/// windows clean on both. The parameters remain for A/B.
/// Opt-in diagnostic `g17p_fastdie_target_cc`: lower the GPU firmware
/// fast-die target (native 11000 = 110.00 C, recorded in the bundle and the
/// secondary +0xb8 object) before the firmware boots.  0 keeps native.
fn g17p_fastdie_target() -> Option<u32> {
    let requested = *crate::module_parameters::g17p_fastdie_target_cc.value();
    match g17_initdata::fast_die_target_override(requested) {
        Ok(target) => target,
        Err(_) => {
            pr_warn!(
                "G17P fast-die: g17p_fastdie_target_cc={} outside {}..={} (lower-only); native kept\n",
                requested,
                g17_initdata::FASTDIE_MIN_TARGET_CC,
                g17_initdata::FASTDIE_NATIVE_TARGET_CC
            );
            None
        }
    }
}

fn g17p_fastdie_apply_status_b(status_b: &mut [u8]) -> Result {
    match g17p_fastdie_target() {
        Some(target) => g17_initdata::apply_fast_die_target_status_b(status_b, target).map_err(|_| EINVAL),
        None => Ok(()),
    }
}

fn g17p_fastdie_apply_bundle(bundle: &mut [u8]) -> Result {
    match g17p_fastdie_target() {
        Some(target) => g17_initdata::apply_fast_die_target_bundle(bundle, target).map_err(|_| EINVAL),
        None => Ok(()),
    }
}

/// Log the GPU fast-die configuration as handed to the firmware.
fn g17p_fastdie_log(bundle: &mut MappedObject, primary_state: &mut MappedObject) -> Result {
    let mut status_b = KVec::<u8>::new();
    primary_state.with_bytes_mut(|bytes| {
        let start = g17_initdata::PRIMARY_STATUS_B_STATE_GRID_OFFSET;
        let end = start + g17_initdata::PRIMARY_STATUS_B_OBJECT_SIZE;
        status_b.extend_from_slice(bytes.get(start..end).ok_or(EINVAL)?, GFP_KERNEL)?;
        Ok(())
    })?;
    bundle.with_bytes_mut(|bytes| {
        let c = g17_initdata::fast_die_config(bytes, &status_b).map_err(|_| EINVAL)?;
        let origin = if c.target_cc == g17_initdata::FASTDIE_NATIVE_TARGET_CC {
            "native"
        } else {
            "DIAGNOSTIC override"
        };
        pr_info!(
            "G17P fast-die: mask {:#x} target {} release {} delta {} (0.01 C) kp {:#010x} ki_dt {:#010x} state {:#x} | live target {} release {} kp {:#010x} ki_dt {:#010x} update {} ({})\n",
            c.mask, c.target_cc, c.release_cc, c.delta_cc, c.kp_bits, c.ki_dt_bits, c.state,
            c.live_target_cc, c.live_release_cc, c.live_kp_bits, c.live_ki_dt_bits, c.live_update, origin
        );
        Ok(())
    })
}

fn g17p_apply_region_c_diagnostic_overrides(bytes: &mut [u8]) -> Result {
    use crate::module_parameters as params;
    if *params::g17p_disable_idle_core_off.value() != 0 {
        // B1 copies RegionC+0x30 to 177838 at init (34f8); 7ca0(1) powers the
        // GPU cores off in the idle descent only when it is nonzero.
        bytes.get_mut(0x30..0x34).ok_or(EINVAL)?.copy_from_slice(&0u32.to_le_bytes());
        pr_info!("G17P RegionC diagnostic: idle core power-off disabled (RegionC+0x30 = 0)\n");
    }
    let fender = *params::g17p_fender_delay.value();
    if fender != 0 {
        bytes.get_mut(0x9bc..0x9c0).ok_or(EINVAL)?.copy_from_slice(&fender.to_le_bytes());
        pr_info!("G17P RegionC diagnostic: fender delay RegionC+0x9bc = {}\n", fender);
    }
    let mask = *params::g17p_timer_cswitch_mask.value();
    let multiplier = *params::g17p_cswitch_timer_multiplier.value();
    if mask != 0 {
        bytes.get_mut(0..4).ok_or(EINVAL)?.copy_from_slice(&mask.to_le_bytes());
    }
    if multiplier != 0 {
        *bytes.get_mut(0x6a).ok_or(EINVAL)? = u8::try_from(multiplier).map_err(|_| EINVAL)?;
    }
    if mask != 0 || multiplier != 0 {
        pr_info!("G17P RegionC diagnostic overrides: TimerCSwitch={:#x} CSwitchTimerMultiplier={:#x}\n",
            mask, multiplier);
    }
    Ok(())
}

#[cfg(not(test))]
fn g17p_mcache_probe_reserve(next: &AtomicU32) -> Option<u8> {
    next.fetch_update(Ordering::AcqRel, Ordering::Acquire, |id| {
        (id >= 96 && id < 192).then_some(id.saturating_add(1))
    }).ok().and_then(|id| u8::try_from(id).ok())
}

/// Nonzero object IDs shared by pool owners and render commands.
/// Keep IDs unique across retained graphs, clients and firmware resets.
#[cfg(not(test))]
static G17P_RENDER_GID_COUNTER: AtomicU32 = AtomicU32::new(1);

#[cfg(not(test))]
fn g17p_render_gid_add(delta: u32) -> Result<(u32, u32)> {
    let mut old = G17P_RENDER_GID_COUNTER.load(Ordering::Acquire);
    loop {
        let new = old.checked_add(delta).ok_or(EOVERFLOW)?;
        match G17P_RENDER_GID_COUNTER.compare_exchange_weak(
            old,
            new,
            Ordering::AcqRel,
            Ordering::Acquire,
        ) {
            Ok(_) => return Ok((old, new)),
            Err(observed) => old = observed,
        }
    }
}

#[cfg(not(test))]
fn g17p_allocate_object_id() -> Result<u32> {
    // Metal reserves 0x01000000 IDs for userspace allocation. Linux has no
    // userspace GID allocator: a pool or lifecycle predecessor needs just one
    // ID. Reserving the whole unused range here exhausts the 32-bit namespace
    // after about 255 render graphs and permanently refuses new clients.
    let (id, _) = g17p_render_gid_add(1)?;
    if id == 0 {
        Err(EOVERFLOW)
    } else {
        Ok(id)
    }
}

#[cfg(not(test))]
fn g17p_allocate_render_lifecycle_pair(predecessor: u32) -> Result<(u64, u64)> {
    // This kernel's OSAddAtomic64 is an arm64 `ldadd`: it returns the value
    // from before the increment. Allocate both IDs in one transaction so the
    // returned old value is 3D's current ID and the following value is TA's.
    let (fragment_current, _) = g17p_render_gid_add(2)?;
    g17_render::g17p_render_lifecycle_pair(predecessor, fragment_current).ok_or(EOVERFLOW)
}

