pub(crate) const EXECUTABLE_T8140_SHARED_UAT_AVAILABLE: bool = true;
/// Production code can allocate and map the source-backed per-role set.
pub(crate) const EXECUTABLE_T8140_ROLE_RESOURCES_AVAILABLE: bool = true;

#[cfg(not(test))]
const ROOT_PAIR_ALLOC_SIZE: usize = 0xc000;
const PRIMARY_STATUS_A_STATE_GRID_OFFSET: u64 = 0xee40;
const PRIMARY_STATUS_A_WORK_SCAN_OFFSET: u64 = 0x0c;
const PRIMARY_STATUS_A_RUNTIME_OFFSET: u64 = 0x10;
const PRIMARY_STATUS_A_POWER_CALLBACK_COUNT_OFFSET: u64 = 0x1c;
const PRIMARY_STATUS_A_WORK_SCAN_STATE_GRID_OFFSET: u64 =
    PRIMARY_STATUS_A_STATE_GRID_OFFSET + PRIMARY_STATUS_A_WORK_SCAN_OFFSET;
const PRIMARY_STATUS_A_RUNTIME_STATE_GRID_OFFSET: u64 =
    PRIMARY_STATUS_A_STATE_GRID_OFFSET + PRIMARY_STATUS_A_RUNTIME_OFFSET;
// Exact J700 A000 firmware-recovery handshake inside primary Status-B. The
// worker clears the EP21 callback before entering this protocol, increments
// +0x48f0, drives +0x4900 through 1 -> 2 and 3 -> 0, then reinstalls it.
const PRIMARY_STATUS_B_FIRMWARE_RECOVERY_EPOCH_OFFSET: u64 = 0x48f0;
const PRIMARY_STATUS_B_FIRMWARE_RECOVERY_STATE_OFFSET: u64 = 0x4900;
const PRIMARY_STATUS_B_RECOVERY_INFO_OFFSET: u64 = 0x40b8;
const PRIMARY_STATUS_B_RECOVERY_INFO_ENTRY_COUNT: usize = 0x100;
const PRIMARY_STATUS_B_RECOVERY_INFO_ENTRY_STRIDE: u64 = 8;
const PRIMARY_STATUS_B_RECOVERY_INFO_EMITTED_COUNT_OFFSET: u64 = 0x48b8;
const PRIMARY_STATUS_B_RECOVERY_ZERO_0_OFFSET: u64 = 0x48bc;
const PRIMARY_STATUS_B_RECOVERY_SOURCE_COUNT_OFFSET: u64 = 0x48c0;
const PRIMARY_STATUS_B_RECOVERY_ZERO_1_OFFSET: u64 = 0x48c4;
const PRIMARY_STATUS_B_RECOVERY_COMMAND_WORD_OFFSET: u64 = 0x48c8;
const PRIMARY_STATUS_B_RECOVERY_RAW_48CC_OFFSET: u64 = 0x48cc;
const PRIMARY_STATUS_B_RECOVERY_RAW_48D0_OFFSET: u64 = 0x48d0;
/// NOT an MMU fault status. B1 copies `(c0d8|c0b0|c0c8)` here, i.e. the
/// hardware-SLOT fault mask that `FUN_5450` scans; the blamed slot in the
/// fault report is its lowest set bit and `detected-source-count` is its
/// population count. Three live samples agree: mask 0x1/slot 0, mask 0x2/
/// slot 1, mask 0x3/slot 0 with source counts 1, 1 and 2.
const PRIMARY_STATUS_B_RECOVERY_SLOT_MASK_OFFSET: u64 = 0x48d8;
const PRIMARY_STATUS_B_RECOVERY_OBJECT_ACTIVE_OFFSET: u64 = 0x4910;
const PRIMARY_FIRMWARE_EVENT_CHANNEL_INDEX: usize = 13;
const SECONDARY_EXTRA_0_BEFORE_PRIMARY_STATUS_A: u64 = 0x6c0;
const SECONDARY_HWDATA_STATE_OFFSET: u64 = 0x3c0;
const FWCTL_SIZE: usize = 0x4000;
/// Size of the KSM completion record in completion ordinal 0.
///
/// Layout established on hardware: four GPU timestamps at +0x10/+0x18/+0x20/
/// +0x28, the submitted descriptor at +0x30 and the CL queue at +0x38. The last
/// field ends at 0x40, so that is the record.
const G17P_COMPUTE_COMPLETION_RECORD_SIZE: usize = 0x40;
/// Bits of a completion-record timestamp that are actually time.
///
/// Firmware RE (`b1` `0xab64`, the KSM completion handler): every timestamp it
/// loads out of a record is immediately masked with `0x3fff_ffff_ffff_ffff`
/// before it is used --
///
/// ```text
/// ldp x8, x9, [x19, #32]            ; +0x20, +0x28
/// and x22, x8, #0x3fffffffffffff
/// and x27, x9, #0x3fffffffffffff
/// ```
///
/// -- so the top ten bits are tag bits, not time. Reading them unmasked is why
/// a record could satisfy "end != 0" while carrying no timestamp at all: tag
/// bits alone make the raw qword non-zero.
const G17P_COMPUTE_COMPLETION_TIMESTAMP_MASK: u64 = 0x003f_ffff_ffff_ffff;
/// Bit 0 of `+0x30` is a flag, not part of the descriptor address.
///
/// Same handler, immediately after loading the pair:
///
/// ```text
/// ldp x22, x20, [x0, #48]           ; +0x30 -> x22, +0x38 -> x20
/// and x26, x22, #0xfffffffffffffffe ; the firmware masks bit 0 off
/// ```
const G17P_COMPUTE_COMPLETION_DESCRIPTOR_MASK: u64 = !1u64;

const G17P_COMPUTE_COMPLETION_QID_COUNT: usize = 128;

#[derive(Debug, Copy, Clone, PartialEq, Eq)]
pub(crate) struct G17PComputeCompletionCandidate {
    /// Pair-A start and pair-B end, preserving the existing compute UAPI ABI.
    pub(crate) timestamps: [u64; 2],
    /// Coherent pair-B interval used only for execution-time diagnostics.
    pub(crate) interval: Option<[u64; 2]>,
    /// Raw pair A and pair B, masked, for the opt-in timing buffer only.
    pub(crate) pairs: [u64; 4],
}

/// One in-flight kick a completion-service transaction looks for, named by
/// its exact queue timestamp (the identity the record's control word carries)
/// and its descriptor.
#[derive(Debug, Copy, Clone)]
struct G17PComputeCompletionRequest {
    queue_id: u8,
    expected_descriptor: u64,
    kick_timestamp: u64,
    pair_a_start: u64,
    pair_a_end: u64,
    pair_b_start: u64,
    pair_b_end: u64,
}

/// Requests of one QID are contiguous in `requests`.
#[derive(Debug, Copy, Clone)]
struct G17PComputeCompletionBatchSlot {
    first: u16,
    count: u16,
}

impl G17PComputeCompletionBatchSlot {
    const EMPTY: Self = Self { first: 0, count: 0 };
}

/// Heap-resident scratch index for one completion-service transaction.
///
/// The manager owns this table so an IRQ never allocates and never places a
/// large descriptor index on the kernel stack. Every published, unretired
/// compute kick whose record the host has not latched yet is requested by
/// its exact queue timestamp and descriptor, grouped by physical QID; the
/// shared completion ring is then decoded once and the matching record of
/// each request is captured.
///
/// The ring is a firmware-internal KSM -> firmware transport, not a history:
/// Neo 2026-09-26 19:56 showed slots out of time order (12..23 older than
/// 9..11, 0..8 newest) with every slot populated, so a record can be
/// overwritten long before 2048 later completions. The caller therefore
/// latches a record the first time any scan sees it and never needs it again.
pub(crate) struct G17PComputeCompletionBatch {
    slots: [G17PComputeCompletionBatchSlot; G17P_COMPUTE_COMPLETION_QID_COUNT],
    requests: KVVec<G17PComputeCompletionRequest>,
    /// QID whose requests are currently being appended; its run must stay
    /// contiguous.
    open_queue: Option<u8>,
}

/// Every completion QID may have its full compute depth in flight, so a
/// request can never be refused for capacity (allocated once, at manager
/// construction; about 112 KiB).
const G17P_COMPUTE_COMPLETION_REQUEST_CAPACITY: usize = G17P_COMPUTE_COMPLETION_QID_COUNT
    * crate::g17_queue_limits::MAX_COMPUTE_IN_FLIGHT_PER_QUEUE as usize;

impl G17PComputeCompletionBatch {
    pub(crate) fn new() -> Result<Self> {
        Ok(Self {
            slots: [G17PComputeCompletionBatchSlot::EMPTY; G17P_COMPUTE_COMPLETION_QID_COUNT],
            requests: KVVec::with_capacity(G17P_COMPUTE_COMPLETION_REQUEST_CAPACITY, GFP_KERNEL)?,
            open_queue: None,
        })
    }

    pub(crate) fn clear(&mut self) {
        self.slots.fill(G17PComputeCompletionBatchSlot::EMPTY);
        self.requests.clear();
        self.open_queue = None;
    }

    /// Request one in-flight kick. All requests of a QID must be made
    /// consecutively; requesting a QID again after another QID is refused.
    pub(crate) fn request(
        &mut self,
        queue_id: u8,
        expected_descriptor: u64,
        kick_timestamp: u64,
    ) -> Result {
        if expected_descriptor == 0 || kick_timestamp == 0 {
            return Err(EINVAL);
        }
        let index = self.requests.len();
        let slot = self.slots.get_mut(usize::from(queue_id)).ok_or(EINVAL)?;
        if slot.count != 0 && self.open_queue != Some(queue_id) {
            return Err(EBUSY);
        }
        // Never allocate here: capacity covers every queue at full depth.
        if index >= self.requests.capacity()
            || usize::from(slot.count) >= crate::g17_queue_limits::MAX_COMPUTE_IN_FLIGHT_PER_QUEUE as usize
        {
            return Err(ENOSPC);
        }
        let first = if slot.count == 0 {
            u16::try_from(index).map_err(|_| EOVERFLOW)?
        } else {
            slot.first
        };
        self.requests.push_within_capacity(G17PComputeCompletionRequest {
            queue_id,
            expected_descriptor,
            kick_timestamp,
            pair_a_start: 0,
            pair_a_end: 0,
            pair_b_start: 0,
            pair_b_end: 0,
        }).map_err(|_| ENOSPC)?;
        slot.first = first;
        slot.count += 1;
        self.open_queue = Some(queue_id);
        Ok(())
    }

    fn fold_record(&mut self, record: &[u8]) -> Result {
        if record.len() != G17P_COMPUTE_COMPLETION_RECORD_SIZE {
            return Err(EINVAL);
        }
        let field = |at: usize| -> Result<u64> {
            Ok(u64::from_le_bytes(
                record.get(at..at + 8).ok_or(ERANGE)?
                    .try_into().map_err(|_| EINVAL)?,
            ))
        };
        let control = field(0x00)?;
        let queue_id = g17_completion::g17p_ksm_completion_queue_id(control);
        let slot = *self.slots.get(usize::from(queue_id)).ok_or(EINVAL)?;
        if slot.count == 0 {
            return Ok(());
        }
        let descriptor = field(0x30)? & G17P_COMPUTE_COMPLETION_DESCRIPTOR_MASK;
        if descriptor == 0 || field(0x38)? == 0 {
            return Ok(());
        }
        // Exact identity: the kick timestamp is unique per QID for 2^40
        // kicks, so neither descriptor-slot reuse (every 256 kicks) nor a
        // retirement floor is needed to reject an older lap's record.
        let kick_timestamp = g17_completion::g17p_ksm_completion_timestamp(control);
        let first = usize::from(slot.first);
        let requests = self.requests
            .get_mut(first..first + usize::from(slot.count))
            .ok_or(ERANGE)?;
        let Some(request) = requests.iter_mut()
            .find(|request| request.expected_descriptor == descriptor
                && request.kick_timestamp == kick_timestamp)
        else {
            return Ok(());
        };
        let pair_a_start = field(0x10)? & G17P_COMPUTE_COMPLETION_TIMESTAMP_MASK;
        let pair_a_end = field(0x18)? & G17P_COMPUTE_COMPLETION_TIMESTAMP_MASK;
        let pair_b_start = field(0x20)? & G17P_COMPUTE_COMPLETION_TIMESTAMP_MASK;
        let pair_b_end = field(0x28)? & G17P_COMPUTE_COMPLETION_TIMESTAMP_MASK;
        // A claimed-but-unstamped record carries tag bits only.
        if pair_a_start == 0 || pair_b_end == 0
            || (request.pair_b_end != 0 && pair_b_end <= request.pair_b_end)
        {
            return Ok(());
        }
        request.pair_a_start = pair_a_start;
        request.pair_a_end = pair_a_end;
        request.pair_b_start = pair_b_start;
        request.pair_b_end = pair_b_end;
        Ok(())
    }

    /// Consume the observation for one exact requested kick.
    pub(crate) fn take(
        &mut self,
        queue_id: u8,
        expected_descriptor: u64,
        kick_timestamp: u64,
    ) -> Result<Option<G17PComputeCompletionCandidate>> {
        let slot = *self.slots.get(usize::from(queue_id)).ok_or(EINVAL)?;
        let first = usize::from(slot.first);
        let requests = self.requests
            .get_mut(first..first + usize::from(slot.count))
            .ok_or(EIO)?;
        let request = requests.iter_mut()
            .find(|request| request.queue_id == queue_id
                && request.expected_descriptor == expected_descriptor
                && request.kick_timestamp == kick_timestamp)
            .ok_or(EIO)?;
        let captured = *request;
        request.pair_a_start = 0;
        request.pair_a_end = 0;
        request.pair_b_start = 0;
        request.pair_b_end = 0;
        if captured.pair_b_end == 0 {
            return Ok(None);
        }
        let interval = (captured.pair_b_start != 0
            && captured.pair_b_start < captured.pair_b_end)
            .then_some([captured.pair_b_start, captured.pair_b_end]);
        Ok(Some(G17PComputeCompletionCandidate {
            timestamps: [captured.pair_a_start, captured.pair_b_end],
            interval,
            pairs: [captured.pair_a_start, captured.pair_a_end,
                captured.pair_b_start, captured.pair_b_end],
        }))
    }
}
/// Offset of the compute completion stamp inside the queue support object.
///
/// This is the word the selector-3 descriptor names at `+0x0F40`, i.e. what
/// the driver already calls `dispatch_a`. Firmware RE (`b1`
/// `AGFAcceleratorProcessTimeStampQueue` at `0x168d0`): after the completion
/// record has been consumed, the firmware issues its GPU cache-maintenance
/// command to `sgx+0x1_8030`, polls `sgx+0x1_8038` bit 1 until it clears,
/// scans the fault units, and only then does
///
/// ```text
/// ldp x26, x21, [x0]        ; x26 = *(descriptor + 0x0F40)
/// ldp w22, w23, [x0, #16]   ; w22 =  descriptor + 0x0F50 (the stamp value)
/// str w22, [x26]            ; the host-visible completion stamp
/// ```
///
/// So the stamp store is the first host-visible event that is ordered AFTER
/// the flush, which is precisely the property a completion needs.
const G17P_COMPUTE_STAMP_SUPPORT_OFFSET: u64 = 0x300;

/// Per-publication channel-command slots. Offsets keep each body at the
/// same 0x400 alignment its queue-graph window had.
const G17P_COMPUTE_RECORD_SLOT_STRIDE: usize = 0x1000;
const G17P_COMPUTE_RECORD_CONFIG: usize = 0x000;
const G17P_COMPUTE_RECORD_EVENT: usize = 0x400;
const G17P_COMPUTE_RECORD_ADD_KICKS: usize = 0x800;
const G17P_COMPUTE_RECORD_STORAGE_SIZE: usize =
    G17P_COMPUTE_RECORD_SLOT_STRIDE * crate::g17_queue_limits::COMPUTE_RECORD_SLOTS;
const _: () = assert!(G17P_COMPUTE_RECORD_CONFIG + g17_compute::COMPUTE_OPTIONAL_SIZE
    <= G17P_COMPUTE_RECORD_EVENT);
const _: () = assert!(G17P_COMPUTE_RECORD_EVENT + g17_compute::COMPUTE_EVENT_SIZE
    <= G17P_COMPUTE_RECORD_ADD_KICKS);
const _: () = assert!(G17P_COMPUTE_RECORD_ADD_KICKS + g17_compute::COMPUTE_ADD_KICKS_SIZE
    <= G17P_COMPUTE_RECORD_SLOT_STRIDE);
const _: () = assert!(g17_submission::G17P_KSM_ADD_KICKS_COMMAND_FETCH_SIZE
    <= g17_compute::COMPUTE_ADD_KICKS_SIZE);

pub(crate) const G17P_CL_ENTRY_STORAGE_SIZE: usize =
    g17_submission::T8140_G17P_HAL200_SKSM_QUEUE_GEOMETRY.backing_size();
pub(crate) const G17P_CL_SHARED_SUPPORT_SIZE: usize = 0x4000;
pub(crate) const G17P_CL_B2_OBJECT_SIZE: usize = 0x4000;
pub(crate) const G17P_CL_CHANNEL_CONTROL_SIZE: usize = 0x4000;
pub(crate) const G17P_CL_SUPPORT_STATE_SIZE: usize = 0x4000;
const G17P_PB_DESCRIPTOR_TABLE_SIZE: usize = 0x4000;
const G17P_UMA_PAGE_POOL_DESCRIPTOR_TABLE_SIZE: usize = 0x4000;
const G17P_LAST_SUBMITTED_HW_TIMESTAMP_COUNT: usize = 128;
const G17P_LAST_SUBMITTED_HW_TIMESTAMP_STRIDE: usize = 0x10;
const G17P_LAST_SUBMITTED_HW_TIMESTAMP_TABLE_SIZE: usize =
    G17P_LAST_SUBMITTED_HW_TIMESTAMP_COUNT * G17P_LAST_SUBMITTED_HW_TIMESTAMP_STRIDE;
/// `AGXQOSManager` constructs its `QOSQueueIDAllocator` with capacity 0x80;
/// firmware's QID/HWBufferID tables have the same 128-entry geometry.
const G17P_QOS_QUEUE_COUNT: usize = 0x80;
/// QoS class selected by `AGXQOSManager::registerQueue` for the valid cold
/// qid0/qid1 render profile.
///
/// Both valid full captures have byte-exact rows `00 0f 00...` for the initial
/// physical qids 0 and 1. Their tag-15 and channel-control class is also 0x0f;
/// Linux's old 0x14 made the QID resource disagree with its own queue class.
/// Kext RE confirms the five-byte table is selected through accelerator policy
/// fields, not by directly indexing it with the outer doorbell priority.
const G17P_DEFAULT_QOS_CLASS: u8 = 0x0f;
/// Native's normalized per-HardwareBufferID share, read out of the same
/// capture's `+0xc00` index row:
///
///     +0xc00: [0x1000, 0x2000, 0x2000, 0x1000, 0x2000, 0, ...]
///
/// The render queue's HardwareBufferID is 4 and its share is 0x2000 == 2^13,
/// i.e. the whole normalization base for a single registered queue. The old
/// `class << 13` form produced 0x28000, which overshoots that base by 20x --
/// it cannot be a normalized share at all.
const G17P_SINGLE_QUEUE_QOS_SHARE: u32 = 0x2000;
/// `AGXArmFirmware::initFirmwareSharedData` publishes this allocation through
/// primary main-config `+0x274`, the fifth pointer in the packed bundle-view
/// array.  The native CPU mapping is `AGXFirmware + 0x2f0`, its firmware GPU
/// pointer is `AGXFirmware + 0x338`, and the allocation is exactly 0x800 bytes.
const G17P_LAST_SUBMITTED_HW_TIMESTAMP_BUNDLE_VIEW_INDEX: usize = 4;
const G17P_LAST_SUBMITTED_HW_TIMESTAMP_BUNDLE_OFFSET: usize =
    g17_initdata::BUNDLE_VIEW_OFFSETS[G17P_LAST_SUBMITTED_HW_TIMESTAMP_BUNDLE_VIEW_INDEX];
pub(crate) const G17P_CL_LOW_VA_START: u64 = 0x70_0000_0000;
pub(crate) const G17P_CL_LOW_VA_END: u64 = 0x71_0000_0000;
/// Dynamic queue, descriptor, and render state live above every native fixed
/// low resource. The lower 32 MiB retain native render/bootstrap coordinates;
/// the next 32 MiB hold an independent compute pool and completion rings.
pub(crate) const G17P_CL_DYNAMIC_LOW_VA_START: u64 = 0x70_0400_0000;
/// Canonical queue mappings must be free in every client root. Independent
/// allocators cannot reserve each other's addresses, so never allocate a
/// client-private render/compute alias in this device-global queue arena.
const G17P_CL_CLIENT_LOW_VA_START: u64 = crate::g17_queue_limits::CLIENT_LOW_VA_START;
/// Architectural base for compact user/GART pointers consumed by the TA.
const G17P_RENDER_USER_BASE: u64 = 0x10_0000_0000;
const G17P_RENDER_USER_END: u64 = 0x11_0000_0000;
/// Dedicated 32-KiB SecureGart scene-scratch object used by native parameter
/// management. Its compact form is 0x178000 and 3D reg 0x1ca28 receives
/// compact+0x20 = 0x178020. This must cover the complete PM allocation, not
/// only one 16-KiB UAT page: dPM owns the scratch object beyond the small
/// host-authored table at its beginning.
const G17P_RENDER_SCENE_SCRATCH_VA: u64 = G17P_RENDER_USER_BASE + 0x178_000;
const G17P_RENDER_SCENE_SCRATCH_MAPPING_SIZE: usize = G17P_PM_SCENE_SCRATCH_SIZE;
/// Persistent 32-KiB discard object consumed as compact pointer 0x180000 by
/// HWPB +0x84. Native maps it GPU-only beside Scene scratch and keeps it
/// across submissions; it is not part of the alternating render-state aliases.
const G17P_RENDER_DISCARD_VA: u64 = G17P_RENDER_USER_BASE + 0x180_000;
/// Client-root address written to the PDM-facing 0x14080 register. Native's
/// cold 3D command uses context-base + 0x1a8000; it is not the firmware-low
/// address of the backing render-state allocation.
const G17P_RENDER_FRAGMENT_STATUS_VA: u64 = G17P_RENDER_USER_BASE + 0x1a_8000;
/// Native leaves an 0x80000-byte fixed-resource window between independently
/// live parameter-buffer managers. Pair 1's scene base is therefore the
/// fault-witnessed 0x10001f8000, while pair 0 retains 0x1000178000.
const G17P_RENDER_FIXED_PAIR_STRIDE: u64 = 0x8_0000;

const fn g17p_render_pair_fixed_va(base: u64, pair: G17PRenderQueuePair) -> Option<u64> {
    base.checked_add(pair.slot() as u64 * G17P_RENDER_FIXED_PAIR_STRIDE)
}

const fn g17p_render_scene_scratch_va(pair: G17PRenderQueuePair) -> Option<u64> {
    g17p_render_pair_fixed_va(G17P_RENDER_SCENE_SCRATCH_VA, pair)
}

const fn g17p_render_discard_va(pair: G17PRenderQueuePair) -> Option<u64> {
    g17p_render_pair_fixed_va(G17P_RENDER_DISCARD_VA, pair)
}

const fn g17p_render_page_list_va(pair: G17PRenderQueuePair) -> Option<u64> {
    g17p_render_pair_fixed_va(g17_submission::G17P_PARTIAL_OPENING_PRIMARY_INDEX_GPU_VA, pair)
}

const fn g17p_render_fragment_status_va(pair: G17PRenderQueuePair) -> Option<u64> {
    g17p_render_pair_fixed_va(G17P_RENDER_FRAGMENT_STATUS_VA, pair)
}
/// Driver-reserved client-root arena for compact aliases of render-state
/// subranges. Every independently live render pair owns two alternating
/// 512-KiB generations, so one pair can stage its next command without
/// colliding with either its prior generation or the other in-flight pair.
/// The slot size is historical -- it once also held the persistent TPC in its
/// tail -- and is kept so that every alias address is unchanged; the TPC now
/// scales with the render target and owns its own arena.
const G17P_RENDER_USER_ALIAS_START: u64 = 0x10_0200_0000;
const G17P_RENDER_USER_ALIAS_SLOT_SIZE: u64 = 0x8_0000;
const G17P_RENDER_ALIAS_GENERATIONS_PER_PAIR: u64 = 2;
const G17P_RENDER_USER_ALIAS_SLOT_COUNT: u64 =
    G17PRenderQueuePair::LEGACY_SLOT_COUNT as u64 * G17P_RENDER_ALIAS_GENERATIONS_PER_PAIR;
const G17P_RENDER_USER_ALIAS_END: u64 = G17P_RENDER_USER_ALIAS_START
    + G17P_RENDER_USER_ALIAS_SLOT_COUNT * G17P_RENDER_USER_ALIAS_SLOT_SIZE;
/// Native RTMemory+0x130..+0x290 contains four 0x58-byte event records per
/// render-target memory object, and every render target owns its own object.
/// Here one TMAP/HMTA arena serves every render queued on a physical pair, so
/// it carries one record per render the pair can hold in flight: a record is
/// reused only after its exact owner retires. Ring distance alone does not
/// prove completion; prepare_rt_slot checks the retained owner explicitly.
const G17P_RENDER_RT_EVENT_RECORD_COUNT: usize = G17P_RENDER_MAX_IN_FLIGHT;
/// The tail-pointer cache and the rotating TMAP/HMTA record are both sized by
/// `g17p_render_state_layout` as
///
///     tpc_size     = 128 * utiles_per_tile * tiles_per_mtile * layers * clusters
///     tilemap_size =  80 * utiles_per_tile * tiles_per_mtile * layers
///
/// i.e. both scale with framebuffer AREA. The fixed carve-outs this driver
/// inherited -- 192 KiB of TPC inside a 512-KiB alias slot, and a 256-KiB
/// record -- hold a 4096x4096 single-sampled target (128 KiB / 80 KiB) and
/// nothing larger: 8192x8192 needs 512 KiB / 320 KiB and the advertised
/// 16384x16384 limit needs 2 MiB / 1.25 MiB. Every larger command was refused
/// with a bare ERANGE out of `restage_command`, which reaches userspace as
/// VK_ERROR_DEVICE_LOST.
///
/// Keep the inherited sizes as FLOORS -- a small render then allocates exactly
/// what it allocated before -- and size anything larger from the command's own
/// layout, in a dedicated compact-GART arena with room to grow in place.
const G17P_RENDER_RT_REGION_FLOOR: usize = 0x4_0000;
const G17P_RENDER_TPC_FLOOR: usize = 0x3_0000;
/// Ceilings for one render pair's two dynamic objects. 32 MiB of TPC covers
/// 16384x16384 at four utiles per tile on both clusters; an 8-MiB record
/// covers the same target, and 2048 layers of any target that fits in RAM.
/// Beyond them the request is refused with a named ERANGE rather than a
/// silent one.
const G17P_RENDER_TPC_MAX_SIZE: usize = 0x200_0000;
const G17P_RENDER_RT_REGION_MAX_STRIDE: usize = 0x80_0000;
const G17P_RENDER_RT_MEMORY_MAX_SIZE: usize =
    G17P_RENDER_RT_EVENT_RECORD_COUNT * G17P_RENDER_RT_REGION_MAX_STRIDE;
/// Dynamic render-target arena, one block per render pair: the TPC first, then
/// the four-record TMAP/HMTA memory. Reserving virtual addresses costs no
/// memory, and both objects keep a stable address for the graph's lifetime so
/// a growth step can replace the backing without moving anything firmware has
/// been told about. It sits above both TVB growth arenas and far below the
/// descending Honeykrisp VDM alias tail at the top of the 4-GiB window.
const G17P_RENDER_RT_DYNAMIC_START: u64 = G17P_RENDER_USER_BASE + 0x5000_0000;
const G17P_RENDER_RT_DYNAMIC_PAIR_STRIDE: u64 =
    (G17P_RENDER_TPC_MAX_SIZE + G17P_RENDER_RT_MEMORY_MAX_SIZE) as u64;
const G17P_RENDER_RT_DYNAMIC_END: u64 = G17P_RENDER_RT_DYNAMIC_START
    + G17PRenderQueuePair::LEGACY_SLOT_COUNT as u64 * G17P_RENDER_RT_DYNAMIC_PAIR_STRIDE;
/// AXFB comes from the queue's ordinary user allocator on macOS, rather than
/// the compact Buffer/Scene allocator used for tilemap and heap metadata.
/// Preserve that separate upper user-GART address class with the same
/// pair-and-generation ownership topology.
const G17P_RENDER_AUX_ALIAS_START: u64 = 0x100_0200_0000;
const G17P_RENDER_AUX_ALIAS_SLOT_SIZE: u64 = G17P_RENDER_STATE_AUX_FB_SIZE as u64;
const G17P_RENDER_AUX_ALIAS_END: u64 =
    G17P_RENDER_AUX_ALIAS_START
        + 128 * G17P_RENDER_AUX_ALIAS_SLOT_SIZE;
/// Native cold parameter-buffer blocks are sparse compact-GART mappings. Each
/// entry names the first of four 32-KiB pages in one 128-KiB block; adjacent
/// blocks normally leave one guard page, while the 0x2a -> 0x4a jump preserves
/// the fixed Scene, discard, and parameter-page-list arena. These 32 values are
/// byte-exact in the valid 092506 cold page-list and UAT captures.
const G17P_NATIVE_TVB_BLOCK_PAGE_IDS: [u32; 32] = [
    0x11, 0x16, 0x1b, 0x20, 0x25, 0x2a, 0x4a, 0x4f,
    0x54, 0x59, 0x5e, 0x63, 0x68, 0x6d, 0x72, 0x77,
    0x7c, 0x81, 0x86, 0x8b, 0x90, 0x95, 0x9a, 0x9f,
    0xa4, 0xa9, 0xae, 0xb3, 0xb8, 0xbd, 0xc2, 0xc7,
];

// The captured cold32 blocks are allocator results, not a hardware limit.
// Keep them stable, then reserve a disjoint compact-GART arena for incremental
// backing beyond the32-MiB command heap and the32..33-MiB render-state aliases.
// Reserving virtual addresses does not allocate any parameter-buffer memory.
const G17P_RENDER_TVB_GROWTH_START: u64 = G17P_RENDER_USER_BASE + 0x0400_0000;
const G17P_RENDER_TVB_GROWTH_END: u64 = G17P_RENDER_TVB_GROWTH_START
    + ((G17P_PM_MAX_OWNED_BLOCKS - G17P_PM_BLOCK_COUNT) * G17P_RENDER_TVB_BLOCK_STRIDE) as u64;
/// A second live PM owner cannot remap the first owner's sparse block VAs.
/// Give every nonzero render pair a complete disjoint compact-GART pool;
/// 0x28000000 is larger than the maximum native 0xd19-block footprint.
const G17P_RENDER_TVB_PAIR_STRIDE: u64 = 0x2800_0000;

fn g17p_tvb_block_page_id(index: usize) -> Option<u32> {
    if let Some(page) = G17P_NATIVE_TVB_BLOCK_PAGE_IDS.get(index) {
        return Some(*page);
    }
    if index >= G17P_PM_MAX_OWNED_BLOCKS { return None; }
    let relative = G17P_RENDER_TVB_GROWTH_START.checked_sub(G17P_RENDER_USER_BASE)?
        .checked_add(((index - G17P_PM_BLOCK_COUNT) as u64)
            .checked_mul(G17P_RENDER_TVB_BLOCK_STRIDE as u64)?)?;
    u32::try_from(relative.checked_div(G17P_PM_PAGE_SIZE as u64)?).ok()
}

fn g17p_native_tvb_block_va(index: usize) -> Option<u64> {
    let page = u64::from(g17p_tvb_block_page_id(index)?);
    G17P_RENDER_USER_BASE.checked_add(page.checked_mul(G17P_PM_PAGE_SIZE as u64)?)
}

fn g17p_render_tvb_block_va(pair: G17PRenderQueuePair, index: usize) -> Option<u64> {
    if pair.slot() == 0 {
        return g17p_native_tvb_block_va(index);
    }
    if index >= G17P_PM_MAX_OWNED_BLOCKS {
        return None;
    }
    G17P_RENDER_TVB_GROWTH_START
        .checked_add(pair.slot() as u64 * G17P_RENDER_TVB_PAIR_STRIDE)?
        .checked_add(index as u64 * G17P_RENDER_TVB_BLOCK_STRIDE as u64)
}

fn g17p_render_tvb_page_id(pair: G17PRenderQueuePair, index: usize) -> Option<u32> {
    let relative = g17p_render_tvb_block_va(pair, index)?
        .checked_sub(G17P_RENDER_USER_BASE)?;
    u32::try_from(relative.checked_div(G17P_PM_PAGE_SIZE as u64)?).ok()
}

/// Allocate only inside compact ranges already reserved from userspace. All
/// channels in a VM share this address budget through the VM's locked allocator;
/// a queue ID neither selects an address nor reserves a maximum-sized TVB.
#[cfg(not(test))]
fn map_g17p_render_compact(
    object: &gem::ObjectRef,
    vm: &mmu::Vm,
    object_range: Range<usize>,
    alignment: u64,
    prot: mmu::Prot,
    guard_size: usize,
) -> Result<mmu::KernelMapping> {
    if object_range.end > object.size() { return Err(EINVAL); }
    let second = G17PRenderQueuePair::for_slot(1).ok_or(EINVAL)?;
    let second_start = g17p_render_tvb_block_va(second, 0).ok_or(EINVAL)?;
    let second_end = g17p_render_tvb_block_va(second, G17P_PM_MAX_OWNED_BLOCKS - 1)
        .and_then(|address| address.checked_add(G17P_RENDER_TVB_BLOCK_STRIDE as u64))
        .ok_or(EOVERFLOW)?;
    for range in [
        G17P_RENDER_USER_ALIAS_START..G17P_RENDER_USER_ALIAS_END,
        G17P_RENDER_TVB_GROWTH_START..G17P_RENDER_TVB_GROWTH_END,
        second_start..second_end,
        G17P_RENDER_RT_DYNAMIC_START..G17P_RENDER_RT_DYNAMIC_END,
    ] {
        match vm.map_in_range_with_guard_size(
            &object.gem, object_range.clone(), alignment, range, prot, guard_size,
        ) {
            Ok(mapping) => return Ok(mapping),
            Err(error) if error == ENOSPC => {},
            Err(error) => return Err(error),
        }
    }
    Err(ENOSPC)
}

fn g17p_compact_tvb_page_id(address: u64) -> Option<u32> {
    let relative = address.checked_sub(G17P_RENDER_USER_BASE)?;
    let end = address.checked_add(G17P_RENDER_TVB_BLOCK_SIZE as u64)?;
    if relative % G17P_PM_PAGE_SIZE as u64 != 0 || end > G17P_RENDER_USER_END {
        return None;
    }
    u32::try_from(relative / G17P_PM_PAGE_SIZE as u64).ok()
}

fn g17p_render_compact_address_matches(
    pair: G17PRenderQueuePair, address: u64, size: usize, bootstrap_address: u64,
) -> bool {
    address >= G17P_RENDER_USER_BASE && address % G17P_PAGE_SIZE as u64 == 0
        && address.checked_add(size as u64).is_some_and(|end| end <= G17P_RENDER_USER_END)
        && (pair.dynamic_placement || address == bootstrap_address)
}

#[cfg(not(test))]
fn g17p_cl_dynamic_low_va_range() -> Range<u64> {
    G17P_CL_DYNAMIC_LOW_VA_START..G17P_CL_CLIENT_LOW_VA_START
}

#[cfg(not(test))]
fn g17p_cl_client_low_va_range() -> Range<u64> {
    G17P_CL_CLIENT_LOW_VA_START..G17P_CL_LOW_VA_END
}

#[cfg(not(test))]
fn map_shared_render_descriptor_range(
    object: &mut gem::ObjectRef,
    client_vm: &mmu::Vm,
    global_vm: &mmu::Vm,
    object_range: Range<usize>,
) -> Result<(mmu::KernelMapping, mmu::KernelMapping)> {
    map_shared_render_range(
        object, client_vm, global_vm, object_range,
        g17p_cl_client_low_va_range(), mmu::PROT_GPU_SHARED_RO,
    )
}

/// Installed queue-context addresses must remain free in every later client
/// VM. Compute's private aliases can occupy the entire client allocation band
/// before that VM first renders. Choose these physical-QID identities in the
/// global allocation band instead, where the shared allocator keeps them
/// disjoint from compute's globally allocated descriptors and pool backing.
#[cfg(not(test))]
fn map_shared_render_sksm_range(
    object: &mut gem::ObjectRef, client_vm: &mmu::Vm, global_vm: &mmu::Vm,
    object_range: Range<usize>, prot: mmu::Prot,
) -> Result<(mmu::KernelMapping, mmu::KernelMapping)> {
    map_shared_render_range(
        object, client_vm, global_vm, object_range,
        g17p_cl_dynamic_low_va_range(), prot,
    )
}

#[cfg(not(test))]
fn map_shared_render_range(
    object: &mut gem::ObjectRef, client_vm: &mmu::Vm, global_vm: &mmu::Vm,
    object_range: Range<usize>, va_range: Range<u64>, prot: mmu::Prot,
) -> Result<(mmu::KernelMapping, mmu::KernelMapping)> {
    let mut search_start = va_range.start;
    loop {
        // The global lower root is the contended side: every live job has a
        // disjoint descriptor view there, while a new client VM is normally
        // empty in this range. Allocate the global address first so its VA
        // manager skips prior jobs directly. Mapping the client first made
        // every global collision synchronously drop/unmap one temporary
        // client mapping under the already deep render constructor.
        let global = object.map_range_into_range(
            global_vm,
            object_range.clone(),
            search_start..va_range.end,
            mmu::UAT_PGSZ as u64,
            prot,
            false,
        )?;
        let start = global.iova();
        let end = start
            .checked_add(object_range.len() as u64)
            .ok_or(EOVERFLOW)?;
        match object.map_range_into_range(
            client_vm,
            object_range.clone(),
            start..end,
            mmu::UAT_PGSZ as u64,
            prot,
            false,
        ) {
            Ok(client) => return Ok((client, global)),
            Err(error) if error == ENOSPC && end < va_range.end => {
                drop(global);
                search_start = end;
            }
            Err(error) => return Err(error),
        }
    }
}

fn clear_g17p_last_submitted_hw_timestamps(bytes: &mut [u8]) -> bool {
    if bytes.len() < G17P_LAST_SUBMITTED_HW_TIMESTAMP_TABLE_SIZE {
        return false;
    }
    for qid in 0..G17P_LAST_SUBMITTED_HW_TIMESTAMP_COUNT {
        let entry = qid * G17P_LAST_SUBMITTED_HW_TIMESTAMP_STRIDE;
        bytes[entry..entry + 4].fill(0);
        bytes[entry + 8..entry + 0x10].fill(0);
    }
    true
}

fn g17p_last_submitted_hw_timestamp_table_mut(bytes: &mut [u8]) -> Option<&mut [u8]> {
    let end = G17P_LAST_SUBMITTED_HW_TIMESTAMP_BUNDLE_OFFSET
        .checked_add(G17P_LAST_SUBMITTED_HW_TIMESTAMP_TABLE_SIZE)?;
    bytes.get_mut(G17P_LAST_SUBMITTED_HW_TIMESTAMP_BUNDLE_OFFSET..end)
}

pub(crate) const G17P_COMPUTE_DESCRIPTOR_SLOT_SIZE: usize = 0x4000;
pub(crate) const G17P_COMPUTE_DESCRIPTOR_SLOT_COUNT: usize =
    g17_submission::T8140_G17P_HAL200_SKSM_QUEUE_GEOMETRY.stamp_count() as usize;
pub(crate) const G17P_COMPUTE_DESCRIPTOR_STORAGE_SIZE: usize =
    G17P_COMPUTE_DESCRIPTOR_SLOT_SIZE * G17P_COMPUTE_DESCRIPTOR_SLOT_COUNT;
pub(crate) const G17P_COMPUTE_PREEMPT_SIZE: usize = 0x4000;
const G17P_COMPUTE_ADD3_RESOURCE_TABLE: usize = 0x14a0;
pub(crate) const G17P_COMPUTE_OPERAND_STATE_SIZE: usize = 0x14000;
pub(crate) const G17P_COMPUTE_SUPPORT_SIZE: usize = 0xc000;
pub(crate) const G17P_COMPUTE_QUEUE_GRAPH_SIZE: usize = g17_compute::COMPUTE_QUEUE_GRAPH_SIZE;
#[cfg(test)]
const G17P_RENDER_DESCRIPTOR_IMAGE_SIZE: usize = 0x8000;
const G17P_RENDER_DESCRIPTOR_SLOT_COUNT: usize = 32;
/// Renders one physical TA/3D pair holds in flight. AGXG17P pipelines up to
/// 80 commands on each of its two AGX3DWorkQueues and orders them only with
/// firmware kick parents; nothing waits for a retirement before the next
/// kick is published. Every per-render resource of a retained pair is sized
/// from this one constant: command generations (render state, DEFLAKE/AXFB
/// aliases, fragment status), TMAP/HMTA records, the queued-tracker FIFO and
/// the scheduler credits. The 32-slot descriptor/timestamp ring, the 35
/// pool-A event records, the 80 PM scenes, the 256-stamp SKSM kick ring and
/// the 0x500-item queue ring each exceed it; the const asserts below keep it
/// that way.
pub(crate) const G17P_RENDER_MAX_IN_FLIGHT: usize = 16;
/// Fixed-placement (bootstrap) pairs carry two alias generations per pair.
const G17P_RENDER_LEGACY_GENERATIONS: usize = 2;
/// Renders that may queue behind the front render of one pair.
pub(crate) const G17P_RENDER_QUEUED_PER_PAIR: usize = G17P_RENDER_MAX_IN_FLIGHT - 1;
const _: () = assert!(G17P_RENDER_RT_EVENT_RECORD_COUNT >= G17P_RENDER_MAX_IN_FLIGHT);
const _: () = assert!(G17P_RENDER_DESCRIPTOR_SLOT_COUNT >= G17P_RENDER_MAX_IN_FLIGHT);
// Pool-A records are reused only after firmware unlinks them; keep headroom
// beyond the in-flight renders for firmware's retirement lag.
const _: () = assert!(35 >= 2 * G17P_RENDER_MAX_IN_FLIGHT);
const _: () = assert!(G17P_PM_SCENE_COUNT >= G17P_RENDER_MAX_IN_FLIGHT);
const G17P_RENDER_TA_DESCRIPTOR_STRIDE: usize = g17_render::TA_DESCRIPTOR_SIZE;
// Each live generation owns its explicit MCache spill table as well as the
// hardware descriptor. Preserve descriptor alignment without padding to a page.
const G17P_RENDER_3D_DESCRIPTOR_STRIDE: usize =
    (g17_render::FRAGMENT_DESCRIPTOR_SIZE
        + (g17_uapi::UAPI_MAX_ATTACHMENTS + 1) * g17_render::G17P_MCACHE_MAPPING_SIZE
        + 0x3f) & !0x3f;
const G17P_RENDER_TA_DESCRIPTOR_ARRAY_SIZE: usize =
    (G17P_RENDER_TA_DESCRIPTOR_STRIDE * G17P_RENDER_DESCRIPTOR_SLOT_COUNT
        + mmu::UAT_PGSZ - 1) & !(mmu::UAT_PGSZ - 1);
const G17P_RENDER_3D_DESCRIPTOR_OFFSET: usize = G17P_RENDER_TA_DESCRIPTOR_ARRAY_SIZE;
const G17P_RENDER_3D_DESCRIPTOR_ARRAY_SIZE: usize =
    (G17P_RENDER_3D_DESCRIPTOR_STRIDE * G17P_RENDER_DESCRIPTOR_SLOT_COUNT
        + mmu::UAT_PGSZ - 1) & !(mmu::UAT_PGSZ - 1);
pub(crate) const G17P_RENDER_DESCRIPTOR_STORAGE_SIZE: usize =
    G17P_RENDER_TA_DESCRIPTOR_ARRAY_SIZE + G17P_RENDER_3D_DESCRIPTOR_ARRAY_SIZE;
/// Only the software sequence's checked increment bounds its lifetime.
/// Physical rings, 40-bit kick timestamps and 32-bit event values wrap
/// independently; none requires restarting a live firmware session.
pub(crate) const G17P_RETAINED_RENDER_ORDINALS: u64 = u64::MAX;
/// Keep the full native 128-entry QID record namespace disjoint from the
/// channel's rings and metadata. Four records happened to fit the old prefix;
/// QID 21 already overlaps its former pointer block at 0x1000.
const G17P_RENDER_QUEUE_METADATA_BASE: usize = 0x8000;
pub(crate) const G17P_RENDER_QUEUE_GRAPH_SIZE: usize = G17P_RENDER_QUEUE_METADATA_BASE + 0x14000;
pub(crate) const G17P_RENDER_SUPPORT_SIZE: usize = 0x40000;

/// Full RT/TVB scans are diagnostics, not part of render retirement. Keep
/// failure/unknown checkpoints and the existing explicit diagnostic request,
/// but avoid walking the entire retained pool on every successful submission.
fn g17p_render_target_scan_due(
    label: &str,
    diagnostic_requested: bool,
    status_read_failed: bool,
) -> bool {
    diagnostic_requested
        || status_read_failed
        || !matches!(label, "pre-doorbell" | "post-completion")
}

