#[derive(Debug, Copy, Clone, PartialEq, Eq)]
pub(crate) enum ResourceError {
    NullUatOwner,
    SplitUatOwner,
    WrongRole,
    SharedLayout,
    RoleLayout,
    InitdataLayout,
}

/// Validate the exact ownership boundary before either root can be published.
pub(crate) fn validate_handoff(
    handoff: &G17ResourceHandoff,
) -> core::result::Result<(), ResourceError> {
    let primary = &handoff.primary;
    let secondary = &handoff.secondary;

    if primary.uat_owner == 0 || secondary.uat_owner == 0 {
        return Err(ResourceError::NullUatOwner);
    }
    if primary.uat_owner != secondary.uat_owner {
        return Err(ResourceError::SplitUatOwner);
    }
    if primary.role != InstanceRole::Primary || secondary.role != InstanceRole::Secondary {
        return Err(ResourceError::WrongRole);
    }

    let primary_main = handoff
        .shared
        .hw_data_bundle
        .checked_add(g17_initdata::NATIVE_PRIMARY_MAIN_BUNDLE_OFFSET as u64)
        .ok_or(ResourceError::SharedLayout)?;
    let secondary_main = handoff
        .shared
        .hw_data_bundle
        .checked_add(g17_initdata::NATIVE_SECONDARY_MAIN_BUNDLE_OFFSET as u64)
        .ok_or(ResourceError::SharedLayout)?;
    if handoff.shared.hw_data_bundle_alloc != g17_initdata::NATIVE_SHARED_CLUSTER_SIZE
        || primary.instance.main_config != primary_main
        || secondary.instance.main_config != secondary_main
    {
        return Err(ResourceError::SharedLayout);
    }

    if primary.instance.status_b
        != primary
            .state_grid
            .checked_add(g17_initdata::PRIMARY_STATUS_B_STATE_GRID_OFFSET as u64)
            .ok_or(ResourceError::RoleLayout)?
        || primary.instance.status_a
            != primary
                .state_grid
                .checked_add(PRIMARY_STATUS_A_STATE_GRID_OFFSET)
                .ok_or(ResourceError::RoleLayout)?
        || secondary.instance.status_b != 0
        || primary.state_grid == secondary.state_grid
        || primary.instance.status_a == secondary.instance.status_a
    {
        return Err(ResourceError::RoleLayout);
    }

    let secondary_extras = [
        primary
            .instance
            .status_a
            .checked_sub(SECONDARY_EXTRA_0_BEFORE_PRIMARY_STATUS_A)
            .ok_or(ResourceError::RoleLayout)?,
        secondary
            .state_grid
            .checked_add(g17_initdata::PRIMARY_STATUS_B_STATE_GRID_OFFSET as u64)
            .ok_or(ResourceError::RoleLayout)?,
    ];
    if primary.instance.secondary_extras != [0, 0]
        || secondary.instance.secondary_extras != secondary_extras
    {
        return Err(ResourceError::RoleLayout);
    }

    g17_initdata::validate_pair(&primary.instance, &secondary.instance)
        .map_err(|_| ResourceError::InitdataLayout)?;

    let mut primary_root = [0u8; g17_initdata::ROOT_SIZE_PRIMARY];
    g17_initdata::encode_root(
        InstanceRole::Primary,
        &handoff.shared,
        &primary.instance,
        &mut primary_root,
    )
    .map_err(|_| ResourceError::InitdataLayout)?;
    let mut secondary_root = [0u8; g17_initdata::ROOT_SIZE_SECONDARY];
    g17_initdata::encode_root(
        InstanceRole::Secondary,
        &handoff.shared,
        &secondary.instance,
        &mut secondary_root,
    )
    .map_err(|_| ResourceError::InitdataLayout)?;

    Ok(())
}

#[cfg(not(test))]
struct MappedObject {
    /// Present for an owning GPU mapping and absent for a subview retained by
    /// another `MappedObject` in the same resource bundle.
    mapping: Option<mmu::KernelMapping>,
    object: gem::ObjectRef,
    iova: u64,
    object_offset: usize,
    logical_size: usize,
    /// Records the existing owning CPU mapping; capture never creates a
    /// physical alias or upgrades a WB observation to GPU-coherent evidence.
    cpu_wc: bool,
    /// v90: nonzero for a pooled firmware-cached command object (family
    /// bit, or `G17P_FW_POOL_POISON` when its attribute state is unproven).
    /// Such an owning mapping is never unmapped while the firmware runs.
    fw_pool: u8,
    fw_node: Option<KBox<G17PPooledFwObject>>,
}

/// Address metadata remains with the shared render graph; owning mappings
/// live in each VM's driver-alias cache instead of pinning the first client.
#[cfg(not(test))]
#[derive(Clone, Copy)]
struct G17PRenderClientAlias {
    address: u64,
    size: usize,
}

#[cfg(not(test))]
impl G17PRenderClientAlias {
    fn new(mapping: &mmu::KernelMapping) -> Self {
        Self { address: mapping.iova(), size: mapping.size() }
    }
    fn from_range(address: u64, size: usize) -> Self { Self { address, size } }
    fn iova(&self) -> u64 { self.address }
    fn size(&self) -> usize { self.size }
}

/// Kernel-owned storage whose GPU mapping belongs only to a render VM.
///
/// The context-0 low root has unrelated B2 aliases inside the render operand
/// arena, so these objects must not acquire a context-0 mapping merely to keep
/// their backing alive.
#[cfg(not(test))]
struct RenderBackingObject {
    object: gem::ObjectRef,
    logical_size: usize,
}

#[cfg(not(test))]
impl RenderBackingObject {
    fn new(dev: &AsahiDevice, size: usize) -> Result<Self> {
        let mut object = gem::new_kernel_object_wc(dev, size)?;
        object.vmap()?.memset(0);
        Ok(Self {
            object,
            logical_size: size,
        })
    }

    fn with_bytes_mut<R>(&mut self, f: impl FnOnce(&mut [u8]) -> Result<R>) -> Result<R> {
        let vmap = self.object.vmap()?;
        let bytes = unsafe {
            // SAFETY: the VMap covers this object's complete, page-rounded
            // allocation and logical_size never exceeds the object size.
            core::slice::from_raw_parts_mut(vmap.as_mut_ptr(), self.logical_size)
        };
        f(bytes)
    }

    fn map_at(
        &mut self,
        vm: &mmu::Vm,
        address: u64,
        prot: mmu::Prot,
    ) -> Result<mmu::KernelMapping> {
        self.object.map_at(vm, address, prot, false)
    }
}

/// One parameter-buffer backing exposed through the native sparse compact-GART
/// block map. The backing keeps the kext's 0x28000 source stride (0x20000 data
/// plus an unmapped 0x8000 guard), while each data block is independently
/// mapped at the exact page ID consumed by PB/TA hardware.
#[cfg(not(test))]
struct G17PRenderTvbExtension {
    first_block: usize,
    block_count: usize,
    backing: RenderBackingObject,
}

#[cfg(not(test))]
struct G17PRenderTvbGrowth {
    extension: G17PRenderTvbExtension,
    mappings: KVec<mmu::KernelMapping>,
    addresses: KVec<u64>,
}

#[cfg(not(test))]
struct G17PRenderTvb {
    queue_pair: G17PRenderQueuePair,
    block_mappings: KVec<mmu::KernelMapping>,
    block_addresses: KVec<u64>,
    block_count: usize,
    primary_block_count: usize,
    backing: RenderBackingObject,
    extensions: KVec<G17PRenderTvbExtension>,
    logical_size: usize,
}

#[cfg(not(test))]
impl G17PRenderTvb {
    fn new(
        dev: &AsahiDevice,
        vm: &mmu::Vm,
        queue_pair: G17PRenderQueuePair,
        render_layout: &G17PRenderStateLayout,
    ) -> Result<Self> {
        if render_layout.tvb_blocks == 0
            || render_layout.tvb_blocks > G17P_PM_MAX_OWNED_BLOCKS
        {
            return Err(ERANGE);
        }

        let mut backing = RenderBackingObject::new(dev, render_layout.tvb_size)?;
        let mut block_mappings =
            KVec::with_capacity(render_layout.tvb_blocks, GFP_KERNEL)?;
        let mut block_addresses = KVec::with_capacity(render_layout.tvb_blocks, GFP_KERNEL)?;
        let mut first_pa = 0u64;
        let mut last_pa = 0u64;

        for index in 0..render_layout.tvb_blocks {
            let source_start = index
                .checked_mul(G17P_RENDER_TVB_BLOCK_STRIDE)
                .ok_or(EOVERFLOW)?;
            let source_end = source_start
                .checked_add(G17P_RENDER_TVB_BLOCK_SIZE)
                .ok_or(EOVERFLOW)?;
            if source_end > backing.logical_size {
                return Err(ERANGE);
            }

            let mapping = if queue_pair.dynamic_placement {
                map_g17p_render_compact(
                    &backing.object, vm, source_start..source_end,
                    G17P_PM_PAGE_SIZE as u64, mmu::PROT_GPU_SHARED_RW,
                    G17P_RENDER_TVB_BLOCK_STRIDE - G17P_RENDER_TVB_BLOCK_SIZE,
                )?
            } else {
                let address = g17p_render_tvb_block_va(queue_pair, index).ok_or(EINVAL)?;
                backing.object.map_range_into_range(
                    vm, source_start..source_end,
                    address..address + G17P_RENDER_TVB_BLOCK_SIZE as u64,
                    G17P_PM_PAGE_SIZE as u64, mmu::PROT_GPU_SHARED_RW, false,
                )?
            };
            let address = mapping.iova();
            let address_end = address.checked_add(G17P_RENDER_TVB_BLOCK_SIZE as u64).ok_or(EOVERFLOW)?;
            g17p_compact_tvb_page_id(address).ok_or(EINVAL)?;
            if mapping.size() < G17P_RENDER_TVB_BLOCK_SIZE
                || !vm.covers_range(
                    address,
                    G17P_RENDER_TVB_BLOCK_SIZE as u64,
                    true,
                    true,
                )
            {
                return Err(EFAULT);
            }

            let block_first_pa = vm.translate_iova(address)?;
            let block_last_pa = vm.translate_iova(
                address_end
                    .checked_sub(mmu::UAT_PGSZ as u64)
                    .ok_or(EOVERFLOW)?,
            )?;
            if index == 0 {
                first_pa = block_first_pa;
            }
            last_pa = block_last_pa;
            block_addresses.push(address, GFP_KERNEL)?;
            block_mappings.push(mapping, GFP_KERNEL)?;
        }

        dev_info!(
            dev.as_ref(),
            "G17P render TVB: native sparse blocks={} first={:#x} last={:#x} backing-size={:#x} backing-pa=[{:#x},{:#x}]\n",
            render_layout.tvb_blocks,
            block_addresses[0],
            block_addresses[render_layout.tvb_blocks - 1],
            render_layout.tvb_size,
            first_pa,
            last_pa,
        );

        Ok(Self {
            queue_pair,
            block_mappings,
            block_addresses,
            block_count: render_layout.tvb_blocks,
            primary_block_count: render_layout.tvb_blocks,
            backing,
            extensions: KVec::new(),
            logical_size: render_layout.tvb_size,
        })
    }

    fn block_backing(&mut self, index: usize) -> Result<(&mut RenderBackingObject, usize)> {
        if index < self.primary_block_count { return Ok((&mut self.backing,index)); }
        for extension in self.extensions.iter_mut() {
            if index >= extension.first_block && index - extension.first_block < extension.block_count {
                return Ok((&mut extension.backing,index-extension.first_block));
            }
        }
        Err(EINVAL)
    }

    fn map_cached_blocks_from(&mut self, vm: &mmu::Vm, first: usize) -> Result<KVec<mmu::KernelMapping>> {
        let count = self.block_count.checked_sub(first).ok_or(EINVAL)?;
        let mut aliases = KVec::with_capacity(count,GFP_KERNEL)?;
        for index in first..self.block_count {
            let address = *self.block_addresses.get(index).ok_or(EINVAL)?;
            let guard_size = if self.queue_pair.dynamic_placement {
                G17P_RENDER_TVB_BLOCK_STRIDE - G17P_RENDER_TVB_BLOCK_SIZE
            } else { 0 };
            let (backing, relative) = self.block_backing(index)?;
            let start = relative.checked_mul(G17P_RENDER_TVB_BLOCK_STRIDE).ok_or(EOVERFLOW)?;
            let end = start.checked_add(G17P_RENDER_TVB_BLOCK_SIZE).ok_or(EOVERFLOW)?;
            if end > backing.logical_size { return Err(ERANGE); }
            aliases.push(vm.map_in_range_with_guard_size(
                &backing.object.gem, start..end, G17P_PM_PAGE_SIZE as u64,
                address..address+(G17P_RENDER_TVB_BLOCK_SIZE + guard_size) as u64,
                mmu::PROT_GPU_SHARED_RW, guard_size,
            )?,GFP_KERNEL)?;
        }
        Ok(aliases)
    }

    /// Install only PTEs on first use; preserve all physical pool blocks.
    fn map_cached_blocks(&mut self, vm: &mmu::Vm) -> Result<KVec<mmu::KernelMapping>> {
        self.map_cached_blocks_from(vm,0)
    }

    fn prepare_growth(&mut self, dev: &AsahiDevice, vm: &mmu::Vm, blocks: usize)
        -> Result<Option<G17PRenderTvbGrowth>>
    {
        if blocks <= self.block_count { return Ok(None); }
        if blocks > G17P_PM_MAX_OWNED_BLOCKS { return Err(ERANGE); }
        let count = blocks - self.block_count;
        let size = (count-1).checked_mul(G17P_RENDER_TVB_BLOCK_STRIDE)
            .and_then(|size| size.checked_add(G17P_RENDER_TVB_BLOCK_SIZE)).ok_or(EOVERFLOW)?;
        self.extensions.reserve(1,GFP_KERNEL)?;
        self.block_addresses.reserve(count,GFP_KERNEL)?;
        let mut backing = RenderBackingObject::new(dev,size)?;
        backing.with_bytes_mut(|bytes| {bytes.fill(0);Ok(())})?;
        let mut mappings = KVec::with_capacity(count,GFP_KERNEL)?;
        let mut addresses = KVec::with_capacity(count,GFP_KERNEL)?;
        for relative in 0..count {
            let index = self.block_count + relative;
            let start = relative.checked_mul(G17P_RENDER_TVB_BLOCK_STRIDE).ok_or(EOVERFLOW)?;
            let mapping = if self.queue_pair.dynamic_placement {
                map_g17p_render_compact(
                    &backing.object, vm, start..start+G17P_RENDER_TVB_BLOCK_SIZE,
                    G17P_PM_PAGE_SIZE as u64, mmu::PROT_GPU_SHARED_RW,
                    G17P_RENDER_TVB_BLOCK_STRIDE - G17P_RENDER_TVB_BLOCK_SIZE,
                )?
            } else {
                let address = g17p_render_tvb_block_va(self.queue_pair, index).ok_or(EINVAL)?;
                backing.object.map_range_into_range(
                    vm, start..start+G17P_RENDER_TVB_BLOCK_SIZE,
                    address..address+G17P_RENDER_TVB_BLOCK_SIZE as u64,
                    G17P_PM_PAGE_SIZE as u64, mmu::PROT_GPU_SHARED_RW, false,
                )?
            };
            g17p_compact_tvb_page_id(mapping.iova()).ok_or(EINVAL)?;
            addresses.push(mapping.iova(),GFP_KERNEL)?;
            mappings.push(mapping,GFP_KERNEL)?;
        }
        Ok(Some(G17PRenderTvbGrowth {
            extension:G17PRenderTvbExtension {first_block:self.block_count,block_count:count,backing},
            mappings,
            addresses,
        }))
    }

    fn with_block_bytes<R>(&mut self,index:usize,f:impl FnOnce(&mut [u8])->Result<R>) -> Result<R> {
        let (backing,relative)=self.block_backing(index)?;
        let start=relative.checked_mul(G17P_RENDER_TVB_BLOCK_STRIDE).ok_or(EOVERFLOW)?;
        backing.with_bytes_mut(|raw| f(raw.get_mut(start..start+G17P_RENDER_TVB_BLOCK_SIZE).ok_or(ERANGE)?))
    }

    fn iova(&self) -> u64 {
        self.block_addresses.first().copied().unwrap_or(0)
    }

    fn with_bytes_mut<R>(&mut self, f: impl FnOnce(&mut [u8]) -> Result<R>) -> Result<R> {
        self.backing.with_bytes_mut(f)
    }

    fn all_reachable_from(&self, vm: &mmu::Vm) -> bool {
        self.block_count >= G17P_PM_BLOCK_COUNT && self.block_count <= G17P_PM_MAX_OWNED_BLOCKS
            && self.logical_size >= (self.block_count - 1) * G17P_RENDER_TVB_BLOCK_STRIDE + G17P_RENDER_TVB_BLOCK_SIZE
            && self.block_addresses.len() >= self.block_count
            && vm.covers_sparse_blocks_with_guards(
                &self.block_addresses[..self.block_count],
                G17P_RENDER_TVB_BLOCK_SIZE as u64,
                G17P_RENDER_TVB_BLOCK_STRIDE as u64,
            )
    }
}

#[cfg(not(test))]
fn map_fixed_object(
    dev: &AsahiDevice,
    vm: &mmu::Vm,
    name: &str,
    address: u64,
    size: usize,
    prot: mmu::Prot,
) -> Result<MappedObject> {
    match MappedObject::new_at(dev, vm, address, size, prot) {
        Ok(mapping) => Ok(mapping),
        Err(error) => {
            dev_err!(
                dev.as_ref(),
                "G17P resources: {} map at {:#x} size {:#x} failed ({:?})\n",
                name,
                address,
                size,
                error
            );
            Err(error)
        }
    }
}

#[cfg(not(test))]
fn mapped_page_mask(vm: &mmu::Vm, address: u64, size: usize) -> u64 {
    let pages = size.div_ceil(mmu::UAT_PGSZ).min(64);
    let mut occupied = 0u64;
    for index in 0..pages {
        let page = address + index as u64 * mmu::UAT_PGSZ as u64;
        if vm.covers_range(page, mmu::UAT_PGSZ as u64, false, false) {
            occupied |= 1 << index;
        }
    }
    occupied
}

#[cfg(not(test))]
fn map_fixed_wc_object(
    dev: &AsahiDevice,
    vm: &mmu::Vm,
    name: &str,
    address: u64,
    size: usize,
    prot: mmu::Prot,
) -> Result<MappedObject> {
    match MappedObject::new_wc_at(dev, vm, address, size, prot) {
        Ok(mapping) => Ok(mapping),
        Err(error) => {
            let occupied = mapped_page_mask(vm, address, size);
            dev_err!(
                dev.as_ref(),
                "G17P resources: {} WC map at {:#x} size {:#x} failed ({:?}), occupied pages={:#x}\n",
                name,
                address,
                size,
                error,
                occupied
            );
            Err(error)
        }
    }
}

#[cfg(not(test))]
struct G17PRetiredRenderTargetBacking {
    _backing: MappedObject,
    owners: [Option<u64>; G17P_RENDER_MAX_IN_FLIGHT],
}

#[cfg(not(test))]
struct G17PRenderTargetMemory {
    queue_pair: G17PRenderQueuePair,
    rt_memory: MappedObject,
    tpc: MappedObject,
    /// Bytes between two rotating TMAP/HMTA records. Sized from the first
    /// command's layout and grown, never shrunk, by `ensure_capacity`.
    record_stride: usize,
    rt_slot_ordinals: [Option<u64>; G17P_RENDER_RT_EVENT_RECORD_COUNT],
    retired_backings: KVec<G17PRetiredRenderTargetBacking>,
}

#[cfg(not(test))]
impl G17PRenderTargetMemory {
    fn prepare_rt_slot(
        &mut self,
        submission_ordinal: u64,
        layout: &G17PRenderStateLayout,
    ) -> Result<G17PRenderTargetAddresses> {
        let slot = submission_ordinal as usize % G17P_RENDER_RT_EVENT_RECORD_COUNT;
        // Ring distance is not retirement proof. The exact owner must be
        // cleared by completion before a different ordinal reuses its bytes.
        if self.rt_slot_ordinals[slot].is_some_and(|previous| previous != submission_ordinal) {
            return Err(EBUSY);
        }
        let used = layout
            .heapmeta
            .checked_add(layout.heapmeta_size)
            .and_then(|end| end.checked_sub(layout.tilemap))
            .ok_or(EINVAL)?;
        if used > self.record_stride {
            return Err(ERANGE);
        }
        let offset = self.record_offset(submission_ordinal);
        let stride = self.record_stride;
        // The record stride is floored at 256 KiB and only ever grows to the
        // largest target this graph has served, so zeroing the whole stride
        // made a 16x16 pass clear a full-screen-or-larger TMAP/HMTA record in
        // write-combined memory under the runtime mutex. This render's
        // descriptors reference only tilemap..heapmeta+heapmeta_size (`used`,
        // checked against the stride above); a later, larger layout on this
        // record zeroes its own span before use. Keep page granularity so the
        // span is never narrower than the page the layout ends in.
        let span = page_align(used).ok_or(EOVERFLOW)?.min(stride);
        self.rt_memory.with_bytes_mut(|raw| {
            raw.get_mut(offset..offset + span)
                .ok_or(ERANGE)?
                .fill(0);
            Ok(())
        })?;
        self.rt_slot_ordinals[slot] = Some(submission_ordinal);
        Ok(G17PRenderTargetAddresses {
            tilemap: self.tilemap_va(submission_ordinal)?,
            layermeta: self.rt_region_va(submission_ordinal, layout, layout.layermeta)?,
            heapmeta: self.heapmeta_va(submission_ordinal, layout)?,
        })
    }

    fn tpc_va(&self) -> u64 {
        self.tpc.iova()
    }

    fn record_offset(&self, submission_ordinal: u64) -> usize {
        g17p_render_rt_record_slot(submission_ordinal) * self.record_stride
    }

    /// Grow the tail-pointer cache and rotating TMAP/HMTA records to what
    /// `layout` needs, retaining backing still referenced by live commands.
    ///
    /// Both sizes scale with framebuffer area, so a retained graph whose next
    /// command has a larger render target must resize rather than refuse: the
    /// previous refusal was a bare `ERANGE` that reached Mesa as
    /// `VK_ERROR_DEVICE_LOST` for every target above 4096x4096.
    ///
    /// Dynamic client graphs may have earlier commands in flight. Each old
    /// allocation retains a snapshot of those exact owners until retirement.
    /// Allocate each replacement before changing its corresponding object;
    /// an earlier successful replacement is retained if a later step fails.
    /// The static bootstrap placement retains its separate regrow path.
    fn ensure_capacity(
        &mut self,
        dev: &AsahiDevice,
        vm: &mmu::Vm,
        layout: &G17PRenderStateLayout,
        owners: &[Option<u64>; G17P_RENDER_MAX_IN_FLIGHT],
    ) -> Result<bool> {
        let tpc_size = g17p_render_tpc_capacity(layout)?;
        let record_stride = g17p_render_rt_region_stride(layout)?;
        let mut grew = false;
        if tpc_size > self.tpc.logical_size {
            if tpc_size > G17P_RENDER_TPC_MAX_SIZE {
                dev_err!(
                    dev.as_ref(),
                    "G17P render: tail-pointer cache needs {:#x} bytes, above the {:#x} ceiling (tiles-per-mtile x utiles-per-tile x layers x clusters); refusing this render target\n",
                    tpc_size,
                    G17P_RENDER_TPC_MAX_SIZE,
                );
                return Err(ERANGE);
            }
            let address = self.tpc.iova();
            let previous = self.tpc.logical_size;
            if self.queue_pair.dynamic_placement {
                // Old descriptors retain the old VA until their exact
                // command generations retire. Reserve before replacing it.
                let retain = owners.iter().any(Option::is_some);
                if retain { self.retired_backings.reserve(1, GFP_KERNEL)?; }
                let replacement = MappedObject::new_wc_render_owned(
                    dev, vm, self.queue_pair, Some(address), tpc_size, mmu::PROT_GPU_FW_SHARED_RW,
                )?;
                let old = core::mem::replace(&mut self.tpc, replacement);
                if retain {
                    self.retired_backings.push_within_capacity(G17PRetiredRenderTargetBacking {
                        _backing: old, owners: *owners,
                    }).map_err(|_| ENOMEM)?;
                }
            } else {
                self.tpc.regrow_wc_at(dev, vm, address, tpc_size)?;
            }
            dev_info!(
                dev.as_ref(),
                "G17P render TPC grew: {:#x} -> {:#x} bytes at {:#x}\n",
                previous,
                tpc_size,
                self.tpc.iova(),
            );
            grew = true;
        }
        if record_stride > self.record_stride {
            if record_stride > G17P_RENDER_RT_REGION_MAX_STRIDE {
                dev_err!(
                    dev.as_ref(),
                    "G17P render: TMAP/HMTA record needs {:#x} bytes, above the {:#x} ceiling; refusing this render target\n",
                    record_stride,
                    G17P_RENDER_RT_REGION_MAX_STRIDE,
                );
                return Err(ERANGE);
            }
            let address = self.rt_memory.iova();
            let size = record_stride
                .checked_mul(G17P_RENDER_RT_EVENT_RECORD_COUNT)
                .ok_or(EOVERFLOW)?;
            let previous = self.record_stride;
            if self.queue_pair.dynamic_placement {
                // Old descriptors retain the old VA until their exact
                // command generations retire. Reserve before replacing it.
                let retain = owners.iter().any(Option::is_some);
                if retain { self.retired_backings.reserve(1, GFP_KERNEL)?; }
                let replacement = MappedObject::new_wc_render_owned(
                    dev, vm, self.queue_pair, Some(address), size, mmu::PROT_GPU_FW_SHARED_RW,
                )?;
                let old = core::mem::replace(&mut self.rt_memory, replacement);
                if retain {
                    self.retired_backings.push_within_capacity(G17PRetiredRenderTargetBacking {
                        _backing: old, owners: *owners,
                    }).map_err(|_| ENOMEM)?;
                }
            } else {
                self.rt_memory.regrow_wc_at(dev, vm, address, size)?;
            }
            self.record_stride = record_stride;
            // Every record moved to fresh, zeroed backing, so no ordinal owns
            // one any more; the reuse guard must start again from empty.
            self.rt_slot_ordinals = [None; G17P_RENDER_RT_EVENT_RECORD_COUNT];
            dev_info!(
                dev.as_ref(),
                "G17P render RT records grew: stride {:#x} -> {:#x}, {:#x} bytes at {:#x}\n",
                previous,
                record_stride,
                size,
                self.rt_memory.iova(),
            );
            grew = true;
        }
        Ok(grew)
    }

    fn tilemap_va(&self, submission_ordinal: u64) -> Result<u64> {
        self.rt_memory
            .iova()
            .checked_add(self.record_offset(submission_ordinal) as u64)
            .ok_or(EOVERFLOW)
    }

    fn rt_region_va(
        &self,
        submission_ordinal: u64,
        layout: &G17PRenderStateLayout,
        region: usize,
    ) -> Result<u64> {
        self.tilemap_va(submission_ordinal)?
            .checked_add(region.checked_sub(layout.tilemap).ok_or(EINVAL)? as u64)
            .ok_or(EOVERFLOW)
    }

    fn heapmeta_va(
        &self,
        submission_ordinal: u64,
        layout: &G17PRenderStateLayout,
    ) -> Result<u64> {
        self.rt_region_va(submission_ordinal, layout, layout.heapmeta)
    }
}

/// The addresses one render-target-memory record publishes to TA and 3D.
#[cfg(not(test))]
#[derive(Debug, Copy, Clone)]
struct G17PRenderTargetAddresses {
    tilemap: u64,
    layermeta: u64,
    heapmeta: u64,
}

/// Keep the comparatively large owning mappings out of
/// `G17PUserRenderStorage::new`'s already deep construction frame. Descriptor
/// dual-root collision retries can synchronously drop a temporary mapping and
/// enter the page-table walker; retaining another full `MappedObject` local in
/// that call chain exhausted the 32-KiB kernel stack on the second client.
#[cfg(not(test))]
#[inline(never)]
fn new_g17p_render_target_memory(
    dev: &AsahiDevice,
    vm: &mmu::Vm,
    queue_pair: G17PRenderQueuePair,
    layout: &G17PRenderStateLayout,
) -> Result<KBox<G17PRenderTargetMemory>> {
    let tpc_size = g17p_render_tpc_capacity(layout)?;
    let record_stride = g17p_render_rt_region_stride(layout)?;
    if tpc_size > G17P_RENDER_TPC_MAX_SIZE
        || record_stride > G17P_RENDER_RT_REGION_MAX_STRIDE
    {
        dev_err!(
            dev.as_ref(),
            "G17P render: render target needs tpc {:#x} (max {:#x}) and record {:#x} (max {:#x})\n",
            tpc_size,
            G17P_RENDER_TPC_MAX_SIZE,
            record_stride,
            G17P_RENDER_RT_REGION_MAX_STRIDE,
        );
        return Err(ERANGE);
    }
    let rt_memory = MappedObject::new_wc_render_owned(
        dev,
        vm,
        queue_pair,
        g17p_render_rt_memory_va(queue_pair),
        record_stride
            .checked_mul(G17P_RENDER_RT_EVENT_RECORD_COUNT)
            .ok_or(EOVERFLOW)?,
        mmu::PROT_GPU_FW_SHARED_RW,
    )?;
    let tpc = MappedObject::new_wc_render_owned(
            dev,
            vm,
            queue_pair,
            g17p_render_tpc_va(queue_pair),
            tpc_size,
            mmu::PROT_GPU_FW_SHARED_RW,
        )?;
    Ok(KBox::new(
        G17PRenderTargetMemory {
            queue_pair,
            rt_memory,
            tpc,
            record_stride,
            rt_slot_ordinals: [None; G17P_RENDER_RT_EVENT_RECORD_COUNT],
            retired_backings: KVec::new(),
        },
        GFP_KERNEL,
    )?)
}

#[cfg(not(test))]
impl MappedObject {
    fn new_wc_in_range_with_guards(
        dev: &AsahiDevice, vm: &mmu::Vm, range: Range<u64>, size: usize,
        alignment: u64, prot: mmu::Prot, guard_pages: usize,
    ) -> Result<Self> {
        let mut object = gem::new_kernel_object_wc(dev, size)?;
        object.vmap()?.memset(0);
        let mapping = vm.map_in_range_with_guards(&object.gem, 0..object.size(),
            alignment, range, prot, guard_pages)?;
        let iova = mapping.iova();
        Ok(Self { mapping: Some(mapping), object, iova, object_offset: 0,
            logical_size: size, cpu_wc: true, fw_node: None, fw_pool: 0 })
    }

    fn map_alias_at_with_guards(&mut self, vm: &mmu::Vm, address: u64,
        prot: mmu::Prot, guard_pages: usize) -> Result<mmu::KernelMapping> {
        if self.object_offset != 0 { return Err(EINVAL); }
        self.object.map_at_with_guards(vm, address, prot, guard_pages)
    }


    fn new_wc_render_owned(
        dev: &AsahiDevice, vm: &mmu::Vm, pair: G17PRenderQueuePair,
        bootstrap_address: Option<u64>, size: usize, prot: mmu::Prot,
    ) -> Result<Self> {
        if !pair.dynamic_placement {
            return Self::new_wc_at(dev, vm, bootstrap_address.ok_or(EINVAL)?, size, prot);
        }
        let mut object = gem::new_kernel_object_wc(dev, size)?;
        object.vmap()?.memset(0);
        let mapping = map_g17p_render_compact(
            &object, vm, 0..size, G17P_PM_PAGE_SIZE as u64, prot, mmu::UAT_PGSZ,
        )?;
        let iova = mapping.iova();
        Ok(Self { mapping: Some(mapping), object, iova, object_offset: 0,
            logical_size: size, cpu_wc: true, fw_pool: 0, fw_node: None })
    }

    fn new_wc_in_range(
        dev: &AsahiDevice,
        vm: &mmu::Vm,
        range: Range<u64>,
        size: usize,
        alignment: u64,
        prot: mmu::Prot,
    ) -> Result<Self> {
        let mut object = gem::new_kernel_object_wc(dev, size)?;
        object.vmap()?.memset(0);
        let mapping = object.map_into_range(vm, range, alignment, prot, true)?;
        let iova = mapping.iova();
        Ok(Self {
            mapping: Some(mapping),
            object,
            iova,
            object_offset: 0,
            logical_size: size,
            cpu_wc: true,
            fw_pool: 0, fw_node: None,
        })
    }

    fn new_wc(
        dev: &AsahiDevice,
        uat: &mmu::Uat,
        size: usize,
        alignment: u64,
        prot: mmu::Prot,
    ) -> Result<Self> {
        Self::new_wc_in_range(
            dev,
            uat.kernel_vm(),
            g17p_dynamic_kernel_va_range(uat.kernel_va_range()?).ok_or(ERANGE)?,
            size,
            alignment,
            prot,
        )
    }

    fn new_wc_at(
        dev: &AsahiDevice,
        vm: &mmu::Vm,
        address: u64,
        size: usize,
        prot: mmu::Prot,
    ) -> Result<Self> {
        let mut object = gem::new_kernel_object_wc(dev, size)?;
        object.vmap()?.memset(0);
        let mapping = object.map_at(vm, address, prot, false)?;
        let iova = mapping.iova();
        Ok(Self {
            mapping: Some(mapping),
            object,
            iova,
            object_offset: 0,
            logical_size: size,
            cpu_wc: true,
            fw_pool: 0, fw_node: None,
        })
    }

    /// Replace this object's backing with a larger one at the SAME address.
    ///
    /// The replacement is allocated and zeroed before the old aperture is
    /// released, so an allocation failure leaves the caller's object intact
    /// and mapped. Only the caller can know that nothing is reading the old
    /// backing; this helper does not synchronize.
    fn regrow_wc_at(
        &mut self,
        dev: &AsahiDevice,
        vm: &mmu::Vm,
        address: u64,
        size: usize,
    ) -> Result {
        if size <= self.logical_size {
            return Ok(());
        }
        // A pooled firmware-cached mapping is never replaced (early unmap).
        if self.fw_pool != 0 {
            return Err(EBUSY);
        }
        let mut object = gem::new_kernel_object_wc(dev, size)?;
        object.vmap()?.memset(0);
        self.mapping = None;
        let mapping = object.map_at(vm, address, mmu::PROT_GPU_FW_SHARED_RW, false)?;
        self.iova = mapping.iova();
        self.mapping = Some(mapping);
        self.object = object;
        self.object_offset = 0;
        self.logical_size = size;
        self.cpu_wc = true;
        Ok(())
    }

    fn new_in_range(
        dev: &AsahiDevice,
        vm: &mmu::Vm,
        range: Range<u64>,
        size: usize,
        alignment: u64,
        prot: mmu::Prot,
    ) -> Result<Self> {
        let mut object = gem::new_kernel_object(dev, size)?;
        object.vmap()?.memset(0);
        let mapping = object.map_into_range(vm, range, alignment, prot, true)?;
        let iova = mapping.iova();
        Ok(Self {
            mapping: Some(mapping),
            object,
            iova,
            object_offset: 0,
            logical_size: size,
            cpu_wc: false,
            fw_pool: 0, fw_node: None,
        })
    }

    fn new(
        dev: &AsahiDevice,
        uat: &mmu::Uat,
        size: usize,
        alignment: u64,
        prot: mmu::Prot,
    ) -> Result<Self> {
        Self::new_in_range(
            dev,
            uat.kernel_vm(),
            g17p_dynamic_kernel_va_range(uat.kernel_va_range()?).ok_or(ERANGE)?,
            size,
            alignment,
            prot,
        )
    }

    fn new_at(
        dev: &AsahiDevice,
        vm: &mmu::Vm,
        address: u64,
        size: usize,
        prot: mmu::Prot,
    ) -> Result<Self> {
        let mut object = gem::new_kernel_object(dev, size)?;
        object.vmap()?.memset(0);
        let mapping = object.map_at(vm, address, prot, false)?;
        let iova = mapping.iova();
        Ok(Self {
            mapping: Some(mapping),
            object,
            iova,
            object_offset: 0,
            logical_size: size,
            cpu_wc: false,
            fw_pool: 0, fw_node: None,
        })
    }

    /// v90: a firmware-cached command object of `family` with its first
    /// `prefix` bytes cached, taken zeroed from the family pool or created by
    /// `alloc` and proven. Falls back to the plain uncached object when the
    /// family is not enabled, the cached-byte cap is reached, or the attribute
    /// change is refused before any PTE mutation. Must run before any pointer
    /// into the object is published.
    fn new_fw_pooled(
        dev: &AsahiDevice,
        uat: &mmu::Uat,
        family: u32,
        size: usize,
        prefix: usize,
        cpu_wc: bool,
        alloc: impl FnOnce() -> Result<Self>,
    ) -> Result<Self> {
        if crate::g17_timing_buffer::fw_cached_family_mask() & family == 0 {
            return alloc();
        }
        let index = g17p_fw_pool_index(family).ok_or(EINVAL)?;
        if let Some(mut object) = g17p_fw_pool_take(index, uat, size, prefix, cpu_wc) {
            object.with_bytes_mut(|bytes| { bytes.fill(0); Ok(()) })?;
            core::sync::atomic::fence(Ordering::SeqCst);
            g17p_fw_pool_bump(1);
            dev_info!(dev.as_ref(),
                "G17P fw-cached object: family={} va={:#x} reused fresh={} reused={} returned={} poisoned={}\n",
                family, object.iova, g17p_fw_pool_stat(0), g17p_fw_pool_stat(1),
                g17p_fw_pool_stat(2), g17p_fw_pool_stat(3));
            return Ok(object);
        }
        let mut object = alloc()?;
        let Some(mapping) = object.mapping.as_ref() else { return Ok(object); };
        let size = object.logical_size as u64;
        // Allocate return storage before changing any PTE. Memory pressure or
        // a peak above cache capacity uses ordinary uncached objects, with no
        // reduced concurrency and no cached mapping lost on a close path.
        let node = match KBox::new(G17PPooledFwObject {
            mapping: None, gem: None, iova: object.iova,
            logical_size: object.logical_size, prefix, cpu_wc, family: family as u8,
        }, GFP_KERNEL) {
            Ok(node) => node,
            Err(_) => return Ok(object),
        };
        {
            let _guard = G17P_FW_POOL_LOCK.lock();
            let used = G17P_FW_POOL_CACHED_BYTES.load(Ordering::Relaxed);
            if G17P_FW_POOL_RESERVED[index].load(Ordering::Relaxed) as usize >= G17P_FW_POOL_SLOTS
                || used.checked_add(size).is_none_or(|n| n > G17P_FW_POOL_CACHED_LIMIT) {
                return Ok(object);
            }
            G17P_FW_POOL_RESERVED[index].fetch_add(1, Ordering::Relaxed);
            G17P_FW_POOL_CACHED_BYTES.fetch_add(size, Ordering::Relaxed);
        }
        object.fw_node = Some(node);
        // SAFETY: `alloc` just created this object; nothing has been published.
        let (proof, mutated) = unsafe { mapping.set_fw_cached_prefix(prefix) };
        match proof {
            Ok(ptes) => {
                object.fw_pool = family as u8;
                g17p_fw_pool_bump(0);
                dev_info!(dev.as_ref(),
                    "G17P fw-cached object: family={} va={:#x} size={:#x} prefix={:#x} ptes={:#x}/{:#x} fresh={} reused={} returned={} poisoned={}\n",
                    family, object.iova, object.logical_size, prefix, ptes[0], ptes[1],
                    g17p_fw_pool_stat(0), g17p_fw_pool_stat(1), g17p_fw_pool_stat(2), g17p_fw_pool_stat(3));
                Ok(object)
            }
            Err(error) if mutated => {
                // Attribute state unproven: never publish, reuse or unmap it.
                object.fw_pool = family as u8 | G17P_FW_POOL_POISON;
                g17p_fw_pool_bump(3);
                dev_err!(dev.as_ref(), "G17P fw-cached object: family={} PTE proof failed ({:?}); retained\n",
                    family, error);
                Err(error)
            }
            Err(_) => {
                {
                    let _guard = G17P_FW_POOL_LOCK.lock();
                    G17P_FW_POOL_RESERVED[index].fetch_sub(1, Ordering::Relaxed);
                    G17P_FW_POOL_CACHED_BYTES.fetch_sub(size, Ordering::Relaxed);
                }
                object.fw_node = None;
                Ok(object)
            }
        }
    }

    fn iova(&self) -> u64 {
        self.iova
    }

    fn with_bytes_mut<R>(&mut self, f: impl FnOnce(&mut [u8]) -> Result<R>) -> Result<R> {
        let vmap = self.object.vmap()?;
        let bytes = unsafe {
            // SAFETY: the VMap covers this object's complete, page-rounded
            // allocation; construction bounds-checks the view offset and size.
            core::slice::from_raw_parts_mut(
                vmap.as_mut_ptr().add(self.object_offset),
                self.logical_size,
            )
        };
        f(bytes)
    }

    fn subview(parent: &Self, offset: usize, logical_size: usize) -> Result<Self> {
        let end = offset.checked_add(logical_size).ok_or(EOVERFLOW)?;
        if end > parent.logical_size {
            return Err(ERANGE);
        }
        Ok(Self {
            mapping: None,
            object: gem::ObjectRef::new(parent.object.gem.clone()),
            iova: parent.iova.checked_add(offset as u64).ok_or(EOVERFLOW)?,
            object_offset: parent.object_offset.checked_add(offset).ok_or(EOVERFLOW)?,
            logical_size,
            cpu_wc: parent.cpu_wc,
            fw_pool: 0, fw_node: None,
        })
    }

    /// Copy only this retained object's existing CPU view into a preallocated
    /// archive. Full expected bytes or an explicit omission; never a short
    /// object padded with zeros. An explicit DVA can name a retained alias.
    fn capture_trace_range(
        &mut self, archive: &mut TraceArchive<'_>, mut meta: TraceMeta,
        offset: usize, size: usize, clock: &mut impl FnMut() -> u64,
    ) -> Result {
        meta.expected_len = size as u64;
        meta.provenance = if self.cpu_wc { trace::Provenance::ExistingOwnedWc }
                          else { trace::Provenance::ExistingOwnedWb };
        if meta.dva == 0 {
            let Some(dva) = self.iova.checked_add(offset as u64) else {
                archive.omit(meta, TraceOmission::InvalidRange).map_err(|_| EINVAL)?;
                return Ok(());
            };
            meta.dva = dva;
        }
        if meta.root == trace::ROOT_UNKNOWN {
            meta.root = if meta.dva & (1u64 << 42) != 0 { trace::ROOT_GLOBAL }
                        else { trace::ROOT_CONTEXT_LOW };
        }
        let Some(end) = offset.checked_add(size).filter(|end| *end <= self.logical_size) else {
            archive.omit(meta, TraceOmission::InvalidRange).map_err(|_| EINVAL)?;
            return Ok(());
        };
        archive.capture(meta, clock, |out| {
            self.with_bytes_mut(|bytes| {
                out.copy_from_slice(&bytes[offset..end]);
                Ok(())
            }).map_err(|_| TraceOmission::ReadError)
        }).map_err(|_| EINVAL)?;
        Ok(())
    }

    fn capture_trace(
        &mut self, archive: &mut TraceArchive<'_>, meta: TraceMeta,
        clock: &mut impl FnMut() -> u64,
    ) -> Result {
        self.capture_trace_range(archive, meta, 0, self.logical_size, clock)
    }

    fn read_live_u32(&mut self, address: u64) -> Result<u32> {
        let offset: usize = address.checked_sub(self.iova()).ok_or(EINVAL)?.try_into()?;
        self.with_bytes_mut(|bytes| g17p_live_read_u32(bytes, offset))
    }

    fn read_u32(&mut self, address: u64) -> Result<u32> {
        let offset = address.checked_sub(self.iova()).ok_or(EINVAL)? as usize;
        let end = offset.checked_add(4).ok_or(EINVAL)?;
        if end > self.logical_size {
            return Err(EINVAL);
        }
        self.with_bytes_mut(|bytes| {
            Ok(u32::from_le_bytes(
                bytes[offset..end].try_into().map_err(|_| EINVAL)?,
            ))
        })
    }

    fn read_u64(&mut self, address: u64) -> Result<u64> {
        let offset = address.checked_sub(self.iova()).ok_or(EINVAL)? as usize;
        let end = offset.checked_add(8).ok_or(EINVAL)?;
        if end > self.logical_size {
            return Err(EINVAL);
        }
        self.with_bytes_mut(|bytes| {
            Ok(u64::from_le_bytes(
                bytes[offset..end].try_into().map_err(|_| EINVAL)?,
            ))
        })
    }

    fn write_u32(&mut self, address: u64, value: u32) -> Result {
        let offset: usize = address.checked_sub(self.iova()).ok_or(EINVAL)?.try_into()?;
        self.with_bytes_mut(|bytes| g17p_live_write_u32(bytes, offset, value))
    }

    fn map_alias_at(
        &mut self,
        vm: &mmu::Vm,
        address: u64,
        prot: mmu::Prot,
    ) -> Result<mmu::KernelMapping> {
        if self.object_offset != 0 {
            return Err(EINVAL);
        }
        self.object.map_at(vm, address, prot, false)
    }

    fn map_alias_in_range(
        &mut self,
        vm: &mmu::Vm,
        range: Range<u64>,
        alignment: u64,
        prot: mmu::Prot,
    ) -> Result<mmu::KernelMapping> {
        if self.object_offset != 0 {
            return Err(EINVAL);
        }
        self.object
            .map_into_range(vm, range, alignment, prot, false)
    }

    fn write_roots(
        &mut self,
        shared: &SharedAddresses,
        primary: &InstanceAddresses,
        secondary: &InstanceAddresses,
    ) -> Result {
        let vmap = self.object.vmap()?;
        let bytes = unsafe {
            // SAFETY: the VMap covers this object's complete, page-rounded
            // allocation and logical_size never exceeds the object size.
            core::slice::from_raw_parts_mut(vmap.as_mut_ptr(), self.logical_size)
        };
        g17_initdata::encode_root(
            InstanceRole::Primary,
            shared,
            primary,
            &mut bytes[..g17_initdata::ROOT_SIZE_PRIMARY],
        )
        .map_err(|_| EINVAL)?;
        let secondary_offset = g17_initdata::SECONDARY_ROOT_DELTA as usize;
        g17_initdata::encode_root(
            InstanceRole::Secondary,
            shared,
            secondary,
            &mut bytes[secondary_offset..secondary_offset + g17_initdata::ROOT_SIZE_SECONDARY],
        )
        .map_err(|_| EINVAL)
    }

    fn write_main_configs(
        &mut self,
        shared: &SharedAddresses,
        primary: &RoleResourceBinding,
        secondary: &RoleResourceBinding,
        primary_views: &g17_initdata::PrimaryRegionViews,
    ) -> Result {
        let vmap = self.object.vmap()?;
        let bytes = unsafe {
            // SAFETY: the VMap covers this object's complete, page-rounded
            // allocation and logical_size never exceeds the object size.
            core::slice::from_raw_parts_mut(vmap.as_mut_ptr(), self.logical_size)
        };
        let primary_offset = g17_initdata::NATIVE_PRIMARY_MAIN_BUNDLE_OFFSET;
        let secondary_offset = g17_initdata::NATIVE_SECONDARY_MAIN_BUNDLE_OFFSET;
        let primary_channels = g17_initdata::derive_channel_table(
            InstanceRole::Primary,
            primary.state_grid,
            primary.instance.status_a,
            primary.instance.main_config,
            shared.hw_data_bundle,
        );
        let secondary_channels = g17_initdata::derive_channel_table(
            InstanceRole::Secondary,
            secondary.state_grid,
            secondary.instance.status_a,
            secondary.instance.main_config,
            shared.hw_data_bundle,
        );
        g17_initdata::encode_main_config(
            InstanceRole::Primary,
            shared,
            &primary.instance,
            &primary_channels,
            Some(primary_views),
            &mut bytes[primary_offset..primary_offset + g17_initdata::MAIN_CONFIG_SIZE],
        )
        .map_err(|_| EINVAL)?;
        g17_initdata::encode_main_config(
            InstanceRole::Secondary,
            shared,
            &secondary.instance,
            &secondary_channels,
            None,
            &mut bytes[secondary_offset..secondary_offset + g17_initdata::MAIN_CONFIG_SIZE],
        )
        .map_err(|_| EINVAL)?;

        let primary_ring = primary_offset + 0x4c0;
        let primary_ring_end = primary_ring
            .checked_add(g17_initdata::control_opening_size(InstanceRole::Primary))
            .ok_or(EINVAL)?;
        g17_initdata::encode_control_opening(
            InstanceRole::Primary,
            bytes
                .get_mut(primary_ring..primary_ring_end)
                .ok_or(EINVAL)?,
        )
        .map_err(|_| EINVAL)?;

        let secondary_ring = secondary_offset + 0x4c0;
        let secondary_ring_end = secondary_ring
            .checked_add(g17_initdata::control_opening_size(
                InstanceRole::Secondary,
            ))
            .ok_or(EINVAL)?;
        g17_initdata::encode_control_opening(
            InstanceRole::Secondary,
            bytes
                .get_mut(secondary_ring..secondary_ring_end)
                .ok_or(EINVAL)?,
        )
        .map_err(|_| EINVAL)
    }
}

#[cfg(not(test))]
fn map_fresh_zero_object_at(
    dev: &AsahiDevice,
    vm: &mmu::Vm,
    address: u64,
    size: usize,
) -> Result<mmu::KernelMapping> {
    // This page is part of the firmware-owned render operand graph. Keep the
    // CPU alias WC so initial zeroes and later firmware stores share one
    // coherent view.
    let mut object = gem::new_kernel_object_wc(dev, size)?;
    object.vmap()?.memset(0);
    object.map_at(vm, address, mmu::PROT_GPU_FW_SHARED_RW, false)
}

#[cfg(not(test))]
fn map_bootstrap_vdm_at(dev: &AsahiDevice, vm: &mmu::Vm) -> Result<mmu::KernelMapping> {
    let mut object = gem::new_kernel_object_wc(dev, G17P_BOOTSTRAP_VDM_SIZE)?;
    let mut vmap = object.vmap()?;
    vmap.memset(0);
    let bytes = unsafe {
        // SAFETY: the VMap covers the complete bootstrap VDM allocation.
        core::slice::from_raw_parts_mut(vmap.as_mut_ptr(), G17P_BOOTSTRAP_VDM_SIZE)
    };
    bytes[..core::mem::size_of::<u32>()]
        .copy_from_slice(&G17P_VDM_STREAM_TERMINATE.to_le_bytes());
    core::mem::drop(vmap);
    object.map_at(
        vm,
        G17P_BOOTSTRAP_VDM_VA,
        mmu::PROT_GPU_FW_SHARED_RW,
        false,
    )
}

#[cfg(not(test))]
fn write_status_block_at(object: &mut MappedObject, offset: usize) -> Result {
    let end = offset
        .checked_add(g17_initdata::STATUS_BLOCK_SIZE)
        .ok_or(EINVAL)?;
    if end > object.logical_size {
        return Err(EINVAL);
    }
    object.with_bytes_mut(|bytes| {
        g17_initdata::encode_status_block(&mut bytes[offset..end]).map_err(|_| EINVAL)
    })
}

#[cfg(not(test))]
fn read_control_counters(object: &mut MappedObject, state_grid: u64) -> Result<[u32; 3]> {
    let base = state_grid
        .checked_add(g17_initdata::WORK_STATE_GRID_OFFSETS
            [g17_initdata::CONTROL_CHANNEL_INDEX] as u64)
        .ok_or(EINVAL)?;
    let mut counters = [0u32; 3];
    for (index, counter) in counters.iter_mut().enumerate() {
        let address = base
            .checked_add(index as u64 * g17_initdata::CHANNEL_STATE_SPACING as u64)
            .ok_or(EINVAL)?;
        *counter = object.read_live_u32(address)?;
    }
    Ok(counters)
}

#[cfg(not(test))]
fn write_control_counters(object: &mut MappedObject, counters: [u32; 3]) -> Result {
    object.with_bytes_mut(|bytes| {
        let control = g17_initdata::WORK_STATE_GRID_OFFSETS
            [g17_initdata::CONTROL_CHANNEL_INDEX];
        for (index, counter) in counters.into_iter().enumerate() {
            let offset = control
                .checked_add(index * g17_initdata::CHANNEL_STATE_SPACING)
                .ok_or(EINVAL)?;
            let end = offset.checked_add(4).ok_or(EINVAL)?;
            bytes
                .get_mut(offset..end)
                .ok_or(EINVAL)?
                .copy_from_slice(&counter.to_le_bytes());
        }
        Ok(())
    })
}

fn register_window_pages(window: &g17_initdata::RegisterWindow) -> Option<(u64, u64, u64)> {
    let page_mask = G17P_PAGE_SIZE as u64 - 1;
    let phys_page = window.phys & !page_mask;
    let device_page = window.device_va & !page_mask;
    if window.phys & page_mask != window.device_va & page_mask {
        return None;
    }
    let end = window.device_va.checked_add(window.size as u64)?;
    let span = end
        .checked_sub(device_page)?
        .checked_add(page_mask)?
        & !page_mask;
    Some((phys_page, device_page, span))
}

#[cfg(not(test))]
fn map_t8140_register_windows(
    dev: &AsahiDevice,
    uat: &mmu::Uat,
) -> Result<KVec<mmu::KernelMapping>> {
    let mut mappings = KVec::new();
    for window in g17_initdata::T8140_REGISTER_WINDOWS {
        let (phys_page, device_page, span) = register_window_pages(&window).ok_or(EINVAL)?;
        let mapping = match uat.kernel_vm().map_io(
            device_page,
            phys_page.try_into()?,
            span.try_into()?,
            mmu::PROT_FW_MMIO_RW,
        ) {
            Ok(mapping) => mapping,
            Err(error) => {
                dev_err!(
                    dev.as_ref(),
                    "G17P resources: register window slot {} map failed ({:#x}:{:#x} -> {:#x}, {:?})\n",
                    window.slot,
                    phys_page,
                    span,
                    device_page,
                    error
                );
                return Err(error);
            }
        };
        if let Err(error) = mappings.push(mapping, GFP_KERNEL) {
            dev_err!(
                dev.as_ref(),
                "G17P resources: retaining register window slot {} failed ({:?})\n",
                window.slot,
                error
            );
            return Err(error.into());
        }
    }
    dev_info!(
        dev.as_ref(),
        "G17P resources: all {} register windows mapped\n",
        g17_initdata::T8140_REGISTER_WINDOWS.len()
    );
    Ok(mappings)
}

/// One logical queue's scheduler-state page (`_AGFISchedulerState`, native
/// AGXCommandQueue `+0x8a0`). Its static image is byte-for-byte what
/// `AGXCommandQueue::allocateSchedulerState` writes: `0xffff` at `+0`, `1` at
/// `+5`, the class byte at `+0x26` and `0xff` at `+0x33`.
///
/// Once a kick has named this page, firmware keeps it on its scheduler lists
/// until the host submits the `0x14` scheduler-state release and the control
/// ring consumer passes that record. That release is the queue teardown's
/// witness; the page itself stays mapped for as long as any installed QID
/// still names it (the manager keeps the last owner of every render pair,
/// and a compute queue keeps its context until the next owner rebinds it).
#[cfg(not(test))]
pub(crate) struct G17PClChannelControl {
    storage: MappedObject,
    /// Set the first time a render graph or CL binding names this page in a
    /// firmware-visible record; never cleared. A page that was never
    /// published is unknown to firmware and needs no release.
    published: AtomicBool,
    /// Non-repeating owner generation, independent of numeric context/QoS ID.
    flist_generation: u32,
}

#[cfg(not(test))]
impl G17PClChannelControl {
    pub(crate) fn new(dev: &AsahiDevice, uat: &mmu::Uat) -> Result<Self> {
        let mut storage = MappedObject::new_wc(
            dev,
            uat,
            G17P_CL_CHANNEL_CONTROL_SIZE,
            mmu::UAT_PGSZ as u64,
            mmu::PROT_GPU_FW_SHARED_RW,
        )?;
        storage.with_bytes_mut(|bytes| {
            g17_submission::apply_g17p_cl_channel_control_static_state(bytes)
                .map_err(|_| EINVAL)
        })?;
        core::sync::atomic::fence(core::sync::atomic::Ordering::SeqCst);
        Ok(Self { storage, published: AtomicBool::new(false),
            flist_generation: g17p_allocate_object_id()? })
    }

    pub(crate) fn flist_generation(&self) -> u32 { self.flist_generation }

    pub(crate) fn gpu_va(&self) -> u64 {
        self.storage.iova()
    }

    pub(crate) fn snapshot_prefix(&self) -> Result<[u8; 0x38]> {
        self.snapshot_bytes()
    }

    pub(crate) fn is_published(&self) -> bool {
        self.published.load(Ordering::Acquire)
    }

    /// Record that a firmware-visible record has named this page. Called
    /// under the runtime mutex by the render and CL binding paths.
    pub(crate) fn mark_published(&self) {
        self.published.store(true, Ordering::Release);
    }

    /// The four identity bytes the scheduler-state release carries back to
    /// firmware: page bytes `[0]`, `[1]`, `[4]` and `[0x26]`, read live because
    /// firmware rewrites the `0xffff` sentinel at `+0` once it adopts the page.
    pub(crate) fn release_identity(&self) -> Result<[u8; 4]> {
        let prefix = self.snapshot_bytes::<0x38>()?;
        Ok([prefix[0x00], prefix[0x01], prefix[0x04], prefix[0x26]])
    }

    /// `g17p_exit_kill`: the firmware-owned bytes the process-exit kill task
    /// consults -- slot byte `[1]`, the QID masks at `+0x12`/`+0x1a` and the
    /// killed word it stores at `+0x34` -- read live from the page.
    pub(crate) fn exit_kill_view(&self) -> Result<crate::g17_exit_kill::StateView> {
        let prefix = self.snapshot_bytes::<{ crate::g17_exit_kill::STATE_KILL_BYTES }>()?;
        Ok(crate::g17_exit_kill::state_view(&prefix))
    }

    fn snapshot_bytes<const N: usize>(&self) -> Result<[u8; N]> {
        if N > self.storage.logical_size { return Err(EINVAL); }
        // Construction established the owning CPU mapping. Acquire a shared
        // read view without modifying the ObjectRef's cached vmap.
        let vmap = self.storage.object.gem.vmap::<u8>()?;
        let mut prefix = [0u8; N];
        core::sync::atomic::fence(core::sync::atomic::Ordering::Acquire);
        for (offset, byte) in prefix.iter_mut().enumerate() {
            // SAFETY: the retained vmap covers this allocation; N is bounded
            // above. Firmware owns these bytes after publication. Volatile
            // reads neither create mutable aliases nor modify its state.
            *byte = unsafe { core::ptr::read_volatile(vmap.as_mut_ptr().add(offset)) };
        }
        Ok(prefix)
    }
}

/// One logical command queue's stable address-space and scheduler identities.
/// Native AGXCommandQueue +0x618 -> reclaimable +0xe0 supplies the same page
/// to TA, 3D and CL. Physical graph reuse must not substitute another owner.
/// Logical teardown publishes opcode 0x14 and waits for control-ring consumption.
/// Installed and previous bindings hold additional references through replacement;
/// uncertain references are retained until the firmware processors stop.
#[cfg(not(test))]
pub(crate) struct G17PLogicalQueueContext {
    /// Zero means the opt-in, non-reusing diagnostic pool was exhausted.
    render_mcache_hwsid: u32,
    render_flists: Arc<kernel::sync::Mutex<KVec<Option<Arc<G17PRenderFlist>>>>>,
    shared_render_flist: bool,
    execution: Arc<mmu::T8140ComputeExecutionContext>,
    work_states: crate::g17_work_state::WorkStatePool,
    tsq: Arc<kernel::sync::Mutex<G17PWorkStateStorage>>,
    tsq_base: u64,
    /// Creating process TGID; never substitute the scheduler worker's PID.
    pub(crate) owner_pid: u32,
    pub(crate) channel_control: Arc<G17PClChannelControl>,
    pub(crate) qos: Arc<G17PLogicalQosLease>,
}

#[cfg(not(test))]
impl G17PLogicalQueueContext {
    pub(crate) fn new(
        execution: Arc<mmu::T8140ComputeExecutionContext>,
        channel_control: Arc<G17PClChannelControl>,
        qos: Arc<G17PLogicalQosLease>,
        owner_pid: u32,
        tsq: Arc<kernel::sync::Mutex<G17PWorkStateStorage>>,
    ) -> Result<Self> {
        let tsq_base = tsq.lock().storage.iova();
        let render_mcache_hwsid = if *crate::module_parameters::g17p_mcache_dsid_probe.value() != 0 {
            let id = g17p_mcache_probe_reserve(&G17P_MCACHE_PROBE_NEXT).map_or(0, u32::from);
            pr_info!("G17P MCache diagnostic: owner-pid={} hwdsid={} non-reusing-pool=96..191\n", owner_pid, id);
            id
        } else { crate::g17_config::RENDER_MCACHE_HWSID };
        let shared_render_flist = crate::g17_host_path::enabled(crate::g17_host_path::SHARED_FLIST);
        let count = if shared_render_flist { 1 } else { 64 };
        let mut render_flists = KVec::with_capacity(count, GFP_KERNEL)?;
        for _ in 0..count { render_flists.push(None, GFP_KERNEL)?; }
        Ok(Self {
            shared_render_flist,
            execution, owner_pid, channel_control, qos, tsq, tsq_base, render_mcache_hwsid,
            work_states: crate::g17_work_state::WorkStatePool::new(),
            render_flists: Arc::pin_init(kernel::new_mutex!(render_flists, "G17 logical render pool"), GFP_KERNEL)?,
        })
    }

    /// Cold graph construction only; publication counters remain serialized
    /// by Runtime. This strong logical-owner identity is deliberately narrower
    /// than assuming that native AGXShared means a VM or process.
    fn render_flist(&self, dev: &AsahiDevice, uat: &mmu::Uat, pair_slot: u8) -> Result<Arc<G17PRenderFlist>> {
        if !self.is_current() { return Err(EFAULT); }
        let index = if self.shared_render_flist { 0 } else { pair_slot as usize };
        let mut pools = self.render_flists.lock();
        let pool = pools.get_mut(index).ok_or(EINVAL)?;
        if let Some(pool) = pool.as_ref() { return Ok(pool.clone()); }
        let created = Arc::new(G17PRenderFlist::new(dev, uat, self.vm())?, GFP_KERNEL)?;
        *pool = Some(created.clone());
        Ok(created)
    }

    /// Teardown-only lookup. The context owns this pool without a reverse Arc.
    pub(crate) fn render_flists_released(&self, released: impl Fn(u32, u64) -> bool) -> bool {
        self.render_flists.lock().iter().flatten().all(|pool|
            released(u32::from(pool.id()), pool.control_shared_va()))
    }

    pub(crate) fn channel_control_gpu_va(&self) -> u64 {
        self.channel_control.gpu_va()
    }

    pub(crate) fn tsq_head_gpu_va(&self) -> u64 {
        self.tsq_base + (mmu::UAT_PGSZ + 0x400) as u64
    }

    fn tsq_head_snapshot(&self) -> Result<[u64; 2]> {
        let storage = self.tsq.lock();
        let view = storage.storage.object.gem.vmap::<u8>()?;
        let mut head = [0; 2];
        for (index, word) in head.iter_mut().enumerate() {
            // SAFETY: two u64-aligned fields in the retained second UAT page.
            *word = u64::from_le(unsafe { core::ptr::read_volatile(
                view.as_mut_ptr().add(mmu::UAT_PGSZ + 0x400 + index * 8).cast::<u64>()) });
        }
        core::sync::atomic::fence(Ordering::Acquire);
        Ok(head)
    }

    pub(crate) fn work_states_exhausted(&self) -> bool {
        !self.work_states.has_free()
    }
}

/// One stable TSQ node and submitted-count cell per live work-state identity.
/// Firmware may mutate the node after publication; only the pointed-to count
/// remains host-owned. This context-local lock protects host initialization and
/// accounting, and is never held while waiting for GPU work or another context.
#[cfg(not(test))]
pub(crate) struct G17PWorkStateStorage {
    storage: MappedObject,
    words: [Option<u32>; crate::g17_work_state::TSQ_STATE_COUNT],
    counts: [u32; crate::g17_work_state::TSQ_STATE_COUNT],
    render_slots: crate::g17_work_state::RenderTsqSlots,
}

#[cfg(not(test))]
impl G17PWorkStateStorage {
    pub(crate) fn new(dev: &AsahiDevice, uat: &mmu::Uat)
        -> Result<Arc<kernel::sync::Mutex<Self>>>
    {
        if crate::g17_work_state::TSQ_STATE_COUNT * crate::g17_work_state::TSQ_NODE_STRIDE
            > mmu::UAT_PGSZ
        {
            return Err(EINVAL);
        }
        // Native CommandBufferState/TSQ nodes are firmware-cached; the second
        // page (submitted counters/head) stays uncached, as native's
        // AGFITimeStampQueue. v90 family bit 2.
        let mut storage = MappedObject::new_fw_pooled(
            dev, uat, G17P_FW_FAMILY_TSQ_NODE, 2 * mmu::UAT_PGSZ, mmu::UAT_PGSZ, true,
            || MappedObject::new_wc(
                dev, uat, 2 * mmu::UAT_PGSZ, mmu::UAT_PGSZ as u64,
                mmu::PROT_GPU_FW_SHARED_RW,
            ),
        )?;
        let head = storage.iova() + (mmu::UAT_PGSZ + 0x400) as u64;
        storage.with_bytes_mut(|raw| {
            put_u64(raw, mmu::UAT_PGSZ + 0x400, 0);
            put_u64(raw, mmu::UAT_PGSZ + 0x408, head);
            put_u32(raw, mmu::UAT_PGSZ + 0x410, 0);
            put_u32(raw, mmu::UAT_PGSZ + 0x414, 0);
            Ok(())
        })?;
        core::sync::atomic::fence(Ordering::Release);
        Arc::pin_init(kernel::new_mutex!(Self {
            storage,
            words: [None; crate::g17_work_state::TSQ_STATE_COUNT],
            counts: [0; crate::g17_work_state::TSQ_STATE_COUNT],
            render_slots: crate::g17_work_state::RenderTsqSlots::new(),
        }, "G17 work-state TSQ storage"), GFP_KERNEL)
    }

    fn initialize(&mut self, word: u32) -> Result {
        let slot = (word & 63) as usize;
        if slot >= self.words.len() { return Err(EINVAL); }
        let node_offset = slot * crate::g17_work_state::TSQ_NODE_STRIDE;
        let count_offset = mmu::UAT_PGSZ + slot * 4;
        let count_address = self.storage.iova() + count_offset as u64;
        self.storage.with_bytes_mut(|bytes| {
            // The WorkStatePool lease proves no prior group can still own
            // this slot. List-unlinked or counter equality alone cannot.
            if !crate::g17_work_state::initialize_tsq_node(
                &mut bytes[node_offset..], count_address, word, 0x50,
            ) { return Err(EINVAL); }
            bytes[count_offset..count_offset + 4].copy_from_slice(&0u32.to_le_bytes());
            Ok(())
        })?;
        self.words[slot] = Some(word);
        self.counts[slot] = 0;
        core::sync::atomic::fence(Ordering::Release);
        Ok(())
    }

    fn change_count(&mut self, word: u32, kicks: u32, add: bool) -> Result<u32> {
        let slot = (word & 63) as usize;
        if self.words.get(slot) != Some(&Some(word)) { return Err(EINVAL); }
        let count = if add { self.counts[slot].checked_add(kicks) }
            else { self.counts[slot].checked_sub(kicks) }.ok_or(EOVERFLOW)?;
        let address = self.storage.iova() + mmu::UAT_PGSZ as u64 + (slot * 4) as u64;
        self.storage.write_u32(address, count)?;
        self.counts[slot] = count;
        core::sync::atomic::fence(Ordering::SeqCst);
        Ok(count)
    }

    fn counters(&self, word: u32) -> Result<[u32; 2]> {
        let slot = (word & 63) as usize;
        if self.words.get(slot) != Some(&Some(word)) { return Err(EINVAL); }
        let vmap = self.storage.object.gem.vmap::<u8>()?;
        let offsets = [mmu::UAT_PGSZ + slot * 4,
            slot * crate::g17_work_state::TSQ_NODE_STRIDE + 0xc];
        let mut counters = [0; 2];
        for (counter, offset) in counters.iter_mut().zip(offsets) {
            // SAFETY: construction retains two aligned UAT pages; both
            // offsets are aligned u32 fields within them. Firmware owns the
            // completion word, so take a volatile snapshot without a mutable
            // reference to the surrounding firmware-owned node.
            *counter = u32::from_le(unsafe {
                core::ptr::read_volatile(vmap.as_mut_ptr().add(offset).cast::<u32>())
            });
        }
        core::sync::atomic::fence(Ordering::Acquire);
        Ok(counters)
    }
}

/// One register-state identity retained through exact command retirement.
/// Publication failure keeps this with the command whenever firmware may
/// have seen it. Error signalling alone must never drop this lease.
#[cfg(not(test))]
pub(crate) struct G17PWorkStateLease {
    context: Arc<G17PLogicalQueueContext>,
    word: AtomicU32,
}

#[cfg(not(test))]
impl G17PWorkStateLease {
    pub(crate) fn new(context: Arc<G17PLogicalQueueContext>) -> Result<Self> {
        let state = Self::deferred(context);
        state.acquire()?;
        Ok(state)
    }

    /// Queued submits consume no hardware state until their first publication.
    pub(crate) fn deferred(context: Arc<G17PLogicalQueueContext>) -> Self {
        Self { context, word: AtomicU32::new(u32::MAX) }
    }

    pub(crate) fn acquire(&self) -> Result<u32> {
        let current = self.word.load(Ordering::Acquire);
        if current != u32::MAX { return Ok(current); }
        let Some(candidate) = self.context.work_states.allocate() else {
            // A concurrent engine may have acquired the last pool slot for
            // this very submit after our first load. Reuse its installed key.
            let installed = self.word.load(Ordering::Acquire);
            return if installed != u32::MAX { Ok(installed) } else { Err(EBUSY) };
        };
        if let Err(error) = self.context.tsq.lock().initialize(candidate) {
            let released = self.context.work_states.release(candidate);
            debug_assert!(released);
            return Err(error);
        }
        match self.word.compare_exchange(u32::MAX, candidate, Ordering::AcqRel, Ordering::Acquire) {
            Ok(_) => Ok(candidate),
            Err(installed) => {
                let released = self.context.work_states.release(candidate);
                debug_assert!(released);
                Ok(installed)
            }
        }
    }

    pub(crate) fn word(&self) -> u32 { self.word.load(Ordering::Acquire) }

    pub(crate) fn tsq_gpu_va(&self) -> Result<u64> {
        let word = self.word();
        if word == u32::MAX { return Err(EINVAL); }
        Ok(self.context.tsq_base
            + u64::from(word & 63) * crate::g17_work_state::TSQ_NODE_STRIDE as u64)
    }

    /// Reserve only kicks which this publication will expose. In particular,
    /// do not pre-count an entire ioctl before finite-capacity chunking: its
    /// first chunk must remain drainable while later chunks await capacity.
    pub(crate) fn add_submitted_kicks(&self, kicks: u32) -> Result<u32> {
        self.context.tsq.lock().change_count(self.word(), kicks, true)
    }

    /// Roll back only a publication proven invisible to firmware. A failure
    /// after possible publication must retain the count and quarantine owner.
    pub(crate) fn cancel_unpublished_kicks(&self, kicks: u32) -> Result<u32> {
        self.context.tsq.lock().change_count(self.word(), kicks, false)
    }

    /// Aggregate diagnostics only: completions from other engines must not
    /// stand in for this command's execution or visibility stamp.
    pub(crate) fn tsq_counters(&self) -> Result<[u32; 2]> {
        self.context.tsq.lock().counters(self.word())
    }

    /// Fault-only owner-wide list observation; never a retirement predicate.
    pub(crate) fn tsq_list_diagnostic(&self) -> Result<(u64, [u64; 2])> {
        Ok((self.context.tsq_head_gpu_va(), self.context.tsq_head_snapshot()?))
    }

    pub(crate) fn render_tsq_slot(&self, pair: u8) -> Result<crate::g17_work_state::TsqSlot> {
        self.context.tsq.lock().render_slots.get_or_assign(pair).ok_or(ENOSPC)
    }

    pub(crate) fn bind_compute_descriptor(&self, descriptor: &mut [u8]) -> Result {
        let slot = crate::g17_work_state::TsqSlot::new(0).ok_or(EINVAL)?;
        if !slot.bind_compute(descriptor, self.tsq_gpu_va()?) { return Err(EINVAL); }
        Ok(())
    }

    pub(crate) fn bind_render_descriptors(
        &self, pair: u8, ta: &mut [u8], fragment: &mut [u8],
    ) -> Result {
        let slot = self.render_tsq_slot(pair)?;
        if !slot.bind_render(ta, fragment, self.tsq_gpu_va()?) { return Err(EINVAL); }
        Ok(())
    }
}

#[cfg(not(test))]
impl Drop for G17PWorkStateLease {
    fn drop(&mut self) {
        // A stale/double release leaves the newer owner intact.
        let word = self.word.load(Ordering::Acquire);
        if word == u32::MAX { return; }
        let released = self.context.work_states.release(word);
        debug_assert!(released);
    }
}

#[cfg(not(test))]
impl core::ops::Deref for G17PLogicalQueueContext {
    type Target = mmu::T8140ComputeExecutionContext;
    fn deref(&self) -> &Self::Target { &self.execution }
}

/// T8140 firmware QoS accounting uses a 24 MHz timebase with the zero epoch
/// adjustments encoded by our HWData. Live accounting-clock snapshots verified
/// that domain independently of command timestamps. Linux CNTPCT can run at
/// 1 GHz; raw architectural ticks cannot be mixed with firmware busy times.
fn g17p_qos_time_from_host(counter: u64, frequency: u64) -> Result<u64> {
    const FIRMWARE_HZ: u64 = 24_000_000;
    // CNTFRQ_EL0's implemented frequency field is 32 bits. Bounding it also
    // keeps the remainder product in u64 without compiler 128-bit division.
    if frequency == 0 || frequency > u64::from(u32::MAX) { return Err(EINVAL); }
    let whole = (counter / frequency).checked_mul(FIRMWARE_HZ).ok_or(EOVERFLOW)?;
    let fraction = (counter % frequency) * FIRMWARE_HZ / frequency;
    whole.checked_add(fraction).ok_or(EOVERFLOW)
}

/// QoS has its own native HardwareBufferIDManager, distinct from PB and FList.
/// Retain this lease in logical queues and installed graph bindings. Rebinding
/// drops the old lease only after all those references retire; keeping an inert
/// scheduler page for firmware lifetime does not pin its QoS credit forever.
#[cfg(not(test))]
pub(crate) struct G17PLogicalQosLease {
    allocator: Arc<kernel::sync::Mutex<u128>>,
    id: u8,
}

#[cfg(not(test))]
impl G17PLogicalQosLease {
    pub(crate) fn new(allocator: Arc<kernel::sync::Mutex<u128>>) -> Result<Arc<Self>> {
        let id = {
            let mut used = allocator.lock();
            let id = used.trailing_ones();
            if id >= 128 { return Err(ENOSPC); }
            *used |= 1u128 << id;
            id as u8
        };
        // On allocation failure the input value is dropped, returning its ID.
        Ok(Arc::new(Self { allocator, id }, GFP_KERNEL)?)
    }
    pub(crate) fn id(&self) -> u8 { self.id }
}

#[cfg(not(test))]
impl Drop for G17PLogicalQosLease {
    fn drop(&mut self) {
        *self.allocator.lock() &= !(1u128 << self.id);
    }
}

/// A retained CL graph's private-memory pool. B1 stores one execution context
/// per FList row, so concurrent graphs in different contexts cannot share it.
#[cfg(not(test))]
pub(crate) struct G17PComputeFlist {
    id: u16,
    backing: MappedObject,
    shared_support: MappedObject,
    support_state: MappedObject,
    submitted: AtomicU64,
}

#[cfg(not(test))]
impl G17PComputeFlist {
    pub(crate) fn new(dev: &AsahiDevice, uat: &mmu::Uat, queue_id: u8) -> Result<Self> {
        if queue_id >= 128 { return Err(EINVAL); }
        let id = crate::g17_config::compute_flist_id(queue_id);
        // One canonical low allocation, also aliased into its current client.
        // Different pools have neither aliased free pages nor duplicate VAs.
        const TABLE: usize = G17P_CONTROL_OPERAND_PAGE_LIST_SIZE;
        const BUFFERS: usize = TABLE + G17P_CONTROL_OPERAND_TABLE_BACKING_SIZE;
        const COUNT: usize = g17_initdata::COMPUTE_READINESS_OPERAND_ENTRY_COUNT;
        let mut backing = MappedObject::new_wc_in_range(
            dev, uat.kernel_lower_vm(), g17p_cl_dynamic_low_va_range(),
            BUFFERS + COUNT * G17P_CONTROL_OPERAND_BUFFER_SIZE,
            mmu::UAT_PGSZ as u64, mmu::PROT_GPU_SHARED_RW,
        )?;
        let page_list_va = backing.iova();
        let run_table_va = page_list_va + TABLE as u64;
        backing.with_bytes_mut(|bytes| {
            for block in 0..COUNT {
                let base = page_list_va + (BUFFERS + block * G17P_CONTROL_OPERAND_BUFFER_SIZE) as u64;
                put_u64(bytes, TABLE + block * 8,
                    (base & G17P_CONTROL_OPERAND_RUN_ADDRESS_MASK)
                        | (G17P_CONTROL_OPERAND_RUN_LENGTH_PAGES << 52));
                for page in 0..G17P_CONTROL_OPERAND_BUFFER_SIZE / 0x1000 {
                    put_u64(bytes, (block * 0x100 + page) * 8, base + page as u64 * 0x1000);
                }
            }
            Ok(())
        })?;
        let mut shared_support = MappedObject::new_wc(
            dev, uat, G17P_CL_SHARED_SUPPORT_SIZE, mmu::UAT_PGSZ as u64,
            mmu::PROT_GPU_FW_SHARED_RW,
        )?;
        let mut support_state = MappedObject::new_wc(
            dev, uat, G17P_CL_SUPPORT_STATE_SIZE, mmu::UAT_PGSZ as u64,
            mmu::PROT_GPU_FW_SHARED_RW,
        )?;
        let target_va = support_state.iova();
        shared_support.with_bytes_mut(|shared| {
            support_state.with_bytes_mut(|target| {
                g17_submission::apply_g17p_cl_flist_static_state(
                    shared, target, page_list_va, run_table_va, target_va, id,
                ).map_err(|_| EINVAL)
            })
        })?;
        core::sync::atomic::fence(Ordering::SeqCst);
        Ok(Self { id, backing, shared_support, support_state, submitted: AtomicU64::new(0) })
    }

    fn map_user_backing(&self, vm: &mmu::Vm) -> Result<mmu::KernelMapping> {
        let mapping = self.backing.mapping.as_ref().ok_or(EINVAL)?;
        mapping.map_alias_into_range(vm, mapping.iova_range(), mmu::PROT_GPU_SHARED_RW)
    }

    /// Account a descriptor before it becomes firmware-visible. The caller
    /// holds the runtime mutex; no other host writer or publication can race.
    /// After this point a failed partial publication must poison the session,
    /// never pretend the firmware has completed this reservation.
    pub(crate) fn reserve_submission(&self) -> Result<u64> {
        let target = self.submitted.load(Ordering::Relaxed)
            .checked_add(1).ok_or(EOVERFLOW)?;
        let vmap = self.support_state.object.gem.vmap::<u64>()?;
        // SAFETY: construction owns a page-aligned, page-sized WC allocation;
        // word zero is the host-owned submitted counter. Runtime serialization
        // protects its sole writer; firmware only observes this word.
        unsafe { core::ptr::write_volatile(vmap.as_mut_ptr(), target.to_le()) };
        core::sync::atomic::fence(Ordering::SeqCst);
        self.submitted.store(target, Ordering::Release);
        Ok(target)
    }

    /// Only after the first publication helper proves it wrote no pointer.
    /// A partially visible group must retain its reservation until stop.
    fn cancel_unpublished_submission(&self, target: u64) -> Result {
        if target == 0 || self.submitted.load(Ordering::Acquire) != target {
            return Err(EINVAL);
        }
        let vmap = self.support_state.object.gem.vmap::<u64>()?;
        // SAFETY: same host-owned word and runtime serialization as reserve.
        unsafe { core::ptr::write_volatile(vmap.as_mut_ptr(), (target - 1).to_le()) };
        core::sync::atomic::fence(Ordering::SeqCst);
        self.submitted.store(target - 1, Ordering::Release);
        Ok(())
    }
}

// Render and compute use the same 256-row firmware namespace. Compute owns
// 1..128; dynamic render pools own 129..255. Reserve the spare bitmap bit.
// The lease follows the pool, never the first physical pair using it.
#[cfg(not(test))]
static G17P_RENDER_FLIST_IDS: [AtomicU64; 2] = [AtomicU64::new(0), AtomicU64::new(1 << 63)];

#[cfg(not(test))]
struct G17PRenderFlistId(u16);
#[cfg(not(test))]
impl G17PRenderFlistId {
    fn new() -> Result<Self> {
        for (bank, used) in G17P_RENDER_FLIST_IDS.iter().enumerate() {
            let mut value = used.load(Ordering::Acquire);
            loop {
                let bit = value.trailing_ones();
                if bit == 64 { break; }
                match used.compare_exchange_weak(value, value | (1u64 << bit), Ordering::AcqRel, Ordering::Acquire) {
                    Ok(_) => return Ok(Self(129 + bank as u16 * 64 + bit as u16)),
                    Err(now) => value = now,
                }
            }
        }
        Err(ENOSPC)
    }
}
#[cfg(not(test))]
impl Drop for G17PRenderFlistId {
    fn drop(&mut self) {
        let bit = self.0 as usize - 129;
        G17P_RENDER_FLIST_IDS[bit / 64].fetch_and(!(1u64 << (bit % 64)), Ordering::Release);
    }
}

/// Shared by one strong logical context's render pairs. The context and its
/// retained graphs/teardown keep the pool and ID alive through release ACK.
#[cfg(not(test))]
pub(crate) struct G17PRenderFlist {
    id: u16,
    // One client alias per pool, removed before its backing or ID lease.
    _client_backing: mmu::KernelMapping,
    client_vm: mmu::Vm,
    backing: MappedObject,
    /// Context 1 owns firmware-side FList service. Its lower root is a
    /// retained render-global VM, not a live view of later kernel-low leaves.
    /// Keep the exact canonical backing aliased there as well as in clients.
    _render_global_backing: mmu::KernelMapping,
    control_shared: MappedObject,
    _control_inner: MappedObject,
    grown: AtomicBool,
    /// Set once the pool has been handed to an owner.
    served: AtomicBool,
    /// Boot-unique identity of this pool object. FList IDs and the pool's
    /// VAs are recycled as soon as a closed context's pool is dropped, so
    /// the next context's new pool can present exactly the previous owner's
    /// (ID, control, run-table, grow-end) tuple. Only this serial tells a
    /// new pool, which needs its UMA descriptor row loaded, from the
    /// retained owner, whose row firmware has been advancing.
    serial: u64,
    _id_lease: G17PRenderFlistId,
}

#[cfg(not(test))]
static G17P_RENDER_FLIST_SERIAL: core::sync::atomic::AtomicU64 = core::sync::atomic::AtomicU64::new(0);

#[cfg(not(test))]
impl G17PRenderFlist {
    pub(crate) fn new(dev: &AsahiDevice, uat: &mmu::Uat, vm: &mmu::Vm) -> Result<Self> {
        let id_lease = G17PRenderFlistId::new()?;
        let id = id_lease.0;
        const PAGE_LIST: usize = G17P_CONTROL_OPERAND_PAGE_LIST_SIZE;
        const RUN_TABLE: usize = G17P_CONTROL_OPERAND_TABLE_BACKING_SIZE;
        const BUFFERS: usize = PAGE_LIST + RUN_TABLE;
        let mut backing = MappedObject::new_wc_in_range(
            dev,
            uat.kernel_lower_vm(),
            g17p_cl_dynamic_low_va_range(),
            BUFFERS + G17P_RENDER_FLIST_INITIAL_BLOCK_COUNT
                * G17P_CONTROL_OPERAND_BUFFER_SIZE,
            mmu::UAT_PGSZ as u64,
            mmu::PROT_GPU_SHARED_RW,
        )?;
        let page_list_va = backing.iova();
        let run_table_va = page_list_va.checked_add(PAGE_LIST as u64).ok_or(EOVERFLOW)?;
        backing.with_bytes_mut(|bytes| {
            bytes.fill(0);
            Self::for_each_pool_word(page_list_va, |at, value| put_u64(bytes, at, value))
        })?;
        let render_global_backing = {
            let mapping = backing.mapping.as_ref().ok_or(EINVAL)?;
            mapping.map_alias_into_range(
                uat.t8140_render_global_vm()?,
                mapping.iova_range(),
                mmu::PROT_GPU_SHARED_RW,
            )?
        };
        let client_backing = {
            let mapping = backing.mapping.as_ref().ok_or(EINVAL)?;
            mapping.map_alias_into_range(vm, mapping.iova_range(), mmu::PROT_GPU_SHARED_RW)?
        };
        let mut control_inner = MappedObject::new_wc(
            dev, uat, mmu::UAT_PGSZ, mmu::UAT_PGSZ as u64,
            mmu::PROT_GPU_FW_SHARED_RW,
        )?;
        control_inner.with_bytes_mut(|bytes| {
            bytes.fill(0);
            // Native updateSubmitInfo increments this submitted-work counter.
            // A fresh pool has no submitted or completed engine commands.
            bytes[..8].copy_from_slice(&0u64.to_le_bytes());
            Ok(())
        })?;
        let inner_va = control_inner.iova();
        let shared_image = Self::control_shared_image(id, page_list_va, run_table_va, inner_va)?;
        let mut control_shared = MappedObject::new_wc(
            dev, uat, g17_initdata::CONTROL_SHARED_OBJECT_SIZE,
            mmu::UAT_PGSZ as u64, mmu::PROT_GPU_FW_SHARED_RW,
        )?;
        control_shared.with_bytes_mut(|bytes| {
            bytes.get_mut(..shared_image.len()).ok_or(EINVAL)?.copy_from_slice(&shared_image);
            Ok(())
        })?;
        core::sync::atomic::fence(Ordering::SeqCst);
        Ok(Self {
            id,
            _client_backing: client_backing,
            client_vm: vm.clone(),
            _id_lease: id_lease,
            backing,
            _render_global_backing: render_global_backing,
            control_shared,
            _control_inner: control_inner,
            grown: AtomicBool::new(true),
            served: AtomicBool::new(false),
            serial: G17P_RENDER_FLIST_SERIAL.fetch_add(1, Ordering::Relaxed) + 1,
        })
    }

    pub(crate) fn serial(&self) -> u64 { self.serial }

    /// Every page-list entry and run slot of the pool's initial image, as
    /// `(byte offset in backing, value)`.
    fn for_each_pool_word(page_list_va: u64, mut put: impl FnMut(usize, u64)) -> Result {
        const BUFFERS: usize =
            G17P_CONTROL_OPERAND_PAGE_LIST_SIZE + G17P_CONTROL_OPERAND_TABLE_BACKING_SIZE;
        for block in 0..G17P_RENDER_FLIST_INITIAL_BLOCK_COUNT {
            let base = page_list_va
                .checked_add((BUFFERS + block * G17P_CONTROL_OPERAND_BUFFER_SIZE) as u64)
                .ok_or(EOVERFLOW)?;
            put(
                G17P_CONTROL_OPERAND_PAGE_LIST_SIZE + block * G17P_CONTROL_OPERAND_RUN_SLOT_SIZE,
                (base & G17P_CONTROL_OPERAND_RUN_ADDRESS_MASK)
                    | (G17P_CONTROL_OPERAND_RUN_LENGTH_PAGES << 52),
            );
            for page in 0..G17P_CONTROL_OPERAND_BUFFER_SIZE / 0x1000 {
                put((block * 0x100 + page) * 8, base + page as u64 * 0x1000);
            }
        }
        Ok(())
    }

    fn control_shared_image(
        id: u16,
        page_list_va: u64,
        run_table_va: u64,
        inner_va: u64,
    ) -> Result<KVVec<u8>> {
        // 16 KiB: never on the kernel stack.
        let mut bytes = KVVec::from_elem(0u8, g17_initdata::CONTROL_SHARED_OBJECT_SIZE, GFP_KERNEL)?;
        g17_initdata::encode_presized_render_control_shared(
            &mut bytes,
            G17P_RENDER_FLIST_INITIAL_BLOCK_COUNT as u32,
        )
        .map_err(|_| EINVAL)?;
        put_u32(&mut bytes, 0x08, u32::from(id));
        put_u64(&mut bytes, 0x14, page_list_va);
        put_u64(&mut bytes, 0x30, run_table_va);
        put_u64(&mut bytes, 0x00, inner_va);
        put_u64(&mut bytes, 0x4c, inner_va);
        Ok(bytes)
    }

    /// Rewrite this pool's complete firmware state to its constructor image.
    ///
    /// Firmware keeps the pool's free-page stack in the page list. Once the
    /// pool has served an owner and been released (0x2e), the list is left
    /// in firmware's used order; registering that released object for its
    /// next owner through a warm tag-15 hung the new owner's first render
    /// on Neo (recycled graphs failed 9/19 processes; a fresh FList object
    /// failed 0/20). Apple writes the whole initial state whenever it
    /// prepares a pool (AGXUSCPrivMemFList::populateInitialFirmwareState).
    /// Call only after firmware has consumed this pool's release.
    pub(crate) fn repopulate(&self) -> Result {
        // A pool that never served an owner still holds its constructor image.
        if !self.served.swap(true, Ordering::AcqRel) {
            return Ok(());
        }
        let page_list_va = self.page_list_va();
        let mut shared_image = Self::control_shared_image(
            self.id,
            page_list_va,
            self.run_table_va(),
            self._control_inner.iova(),
        )?;
        // Only a released pool can be repopulated. Native initializes the
        // completed counter to the current submitted counter, not zero.
        let submitted = self.prepare_submitted_operations(0)?.next;
        put_u64(&mut shared_image, 0x54, submitted);
        // One kernel mapping per object; every write is bounds- and
        // alignment-checked against that object's logical size.
        let write_all = |object: &MappedObject,
                         fill: &mut dyn FnMut(&mut dyn FnMut(usize, u64) -> Result) -> Result|
         -> Result {
            let vmap = object.object.gem.vmap::<u8>()?;
            let base = vmap.as_mut_ptr();
            let size = object.logical_size;
            let mut put = |at: usize, value: u64| -> Result {
                if at % 8 != 0 || at.checked_add(8).is_none_or(|end| end > size) {
                    return Err(ERANGE);
                }
                // SAFETY: checked above; the host alone writes a released
                // pool, under the runtime mutex.
                unsafe { core::ptr::write_volatile(base.add(at).cast::<u64>(), value) };
                Ok(())
            };
            fill(&mut put)
        };
        write_all(&self.backing, &mut |put| {
            let mut result = Ok(());
            Self::for_each_pool_word(page_list_va, |at, value| {
                if result.is_ok() {
                    result = put(at, value);
                }
            })?;
            result
        })?;
        write_all(&self.control_shared, &mut |put| {
            for (index, chunk) in shared_image.chunks(8).enumerate() {
                let mut word = [0u8; 8];
                word[..chunk.len()].copy_from_slice(chunk);
                put(index * 8, u64::from_le_bytes(word))?;
            }
            Ok(())
        })?;
        core::sync::atomic::fence(Ordering::SeqCst);
        Ok(())
    }

    fn prepare_submitted_operations(&self, kicks: u32) -> Result<G17PFlistSubmittedOperation<'_>> {
        let object = &self._control_inner;
        let offset = object.object_offset;
        let size = object.object.size();
        let vmap = object.object.gem.vmap::<u8>()?;
        let raw = unsafe {
            // SAFETY: the VMap covers this owned object; the helper checks
            // the complete counter range before publication can write it.
            core::slice::from_raw_parts(vmap.as_ptr(), size)
        };
        let next = g17p_flist_submitted_next(raw, offset, kicks).ok_or(ERANGE)?;
        Ok(G17PFlistSubmittedOperation { vmap, size, offset, next })
    }

    fn completion_counters(&self) -> Result<[u64; 2]> {
        let submitted = self.prepare_submitted_operations(0)?.next;
        let vmap = self.control_shared.object.gem.vmap::<u8>()?;
        let mut bytes = [0u8; 8];
        for (i, byte) in bytes.iter_mut().enumerate() {
            // SAFETY: state+54..5c is within this retained control object.
            *byte = unsafe { core::ptr::read_volatile(vmap.as_ptr().add(
                self.control_shared.object_offset + 0x54 + i)) };
        }
        Ok([submitted, u64::from_le_bytes(bytes)])
    }

    pub(crate) fn id(&self) -> u16 { self.id }
    pub(crate) fn control_shared_va(&self) -> u64 { self.control_shared.iova() }
    pub(crate) fn page_list_va(&self) -> u64 { self.backing.iova() }
    pub(crate) fn run_table_va(&self) -> u64 {
        self.backing.iova() + G17P_CONTROL_OPERAND_PAGE_LIST_SIZE as u64
    }
    pub(crate) fn grow_end_va(&self) -> u64 {
        self.run_table_va() + G17P_RENDER_FLIST_INITIAL_BLOCK_COUNT as u64
            * G17P_CONTROL_OPERAND_RUN_SLOT_SIZE as u64
    }
    pub(crate) fn needs_grow(&self) -> bool { !self.grown.load(Ordering::Acquire) }
    pub(crate) fn mark_grown(&self) { self.grown.store(true, Ordering::Release); }
    pub(crate) fn map_user_backing(&self, vm: &mmu::Vm) -> Result<mmu::KernelMapping> {
        let mapping = self.backing.mapping.as_ref().ok_or(EINVAL)?;
        mapping.map_alias_into_range(vm, mapping.iova_range(), mmu::PROT_GPU_SHARED_RW)
    }

    fn uma_state(&self) -> Result<g17_submission::G17PUmaPagePoolState> {
        let vmap = self.control_shared.object.gem.vmap::<u8>()?;
        let raw = unsafe {
            // SAFETY: construction retained a complete CONTROL_SHARED object;
            // these unaligned fields are inside it and firmware may update
            // them, so copy with volatile byte reads after an acquire fence.
            core::slice::from_raw_parts(vmap.as_mut_ptr(), self.control_shared.logical_size)
        };
        core::sync::atomic::fence(Ordering::Acquire);
        let read_u32 = |at: usize| -> Result<u32> {
            let mut bytes = [0u8; 4];
            for (index, byte) in bytes.iter_mut().enumerate() {
                *byte = unsafe { core::ptr::read_volatile(raw.as_ptr().add(at + index)) };
            }
            Ok(u32::from_le_bytes(bytes))
        };
        let read_u64 = |at: usize| -> Result<u64> {
            let mut bytes = [0u8; 8];
            for (index, byte) in bytes.iter_mut().enumerate() {
                *byte = unsafe { core::ptr::read_volatile(raw.as_ptr().add(at + index)) };
            }
            Ok(u64::from_le_bytes(bytes))
        };
        Ok(g17_submission::G17PUmaPagePoolState {
            page_list: read_u64(0x14)?,
            unit_pages: read_u32(0x1c)?,
            counter_a: read_u32(0x20)?,
            counter_b: read_u32(0x24)?,
            empty: read_u32(0x28)?,
            total_pages: read_u32(0x2c)?,
        })
    }

    fn store_uma_state(&self, state: g17_submission::G17PUmaPagePoolState) -> Result {
        let vmap = self.control_shared.object.gem.vmap::<u8>()?;
        for (offset, value) in [
            (0x20, state.counter_a),
            (0x24, state.counter_b),
            (0x28, state.empty),
            (0x2c, state.total_pages),
        ] {
            for (index, byte) in value.to_le_bytes().into_iter().enumerate() {
                // SAFETY: these fields are within the retained control
                // object. The caller has retired TA, 3D and FList references
                // before transferring the physical pool slot to another owner.
                unsafe { core::ptr::write_volatile(vmap.as_mut_ptr().add(offset + index), byte) };
            }
        }
        core::sync::atomic::fence(Ordering::SeqCst);
        Ok(())
    }
}

/// Queue-owned mappings retained from SKSM registration through completion.
#[cfg(not(test))]
pub(crate) struct G17PClRuntimeStorage {
    entries: MappedObject,
    /// Upper-root alias of the exact GEM subrange owned by `entries`.
    /// `KernelMapping` retains its own GEM reference for the full alias life.
    entries_high: mmu::KernelMapping,
    geometry: g17_submission::G17SksmQueueGeometry,
    /// Keeps both canonical GPU mappings alive, including after queue close.
    flist: Arc<G17PComputeFlist>,
    /// Views of the canonical pool, never initialized by queue construction.
    shared_support: MappedObject,
    support_state: MappedObject,
    /// Independent retained scheduler bytes; not part of the shared FList.
    scheduler_support: MappedObject,
    scheduler_state: MappedObject,
}

/// Queue-owned objects referenced by selector-3 compute descriptors.
///
/// Descriptor slots keep both views required by the command ABI: firmware
/// consumes the upper address carried in the CL entry, while descriptor-local
/// register-array pointers use the lower alias. All 256 slots remain mapped
/// until the physical queue is unregistered.
#[cfg(not(test))]
pub(crate) struct G17PComputeDescriptorStorage {
    descriptors: MappedObject,
    descriptors_high: mmu::KernelMapping,
    preempt: MappedObject,
    robustness: MappedObject,
    operand_state: MappedObject,
    support: MappedObject,
    queue_graph: MappedObject,
    queue_context_low: MappedObject,
    queue_context_high: MappedObject,
    /// Per-publication tag-15/16/14 channel-command bodies, one
    /// `G17P_COMPUTE_RECORD_SLOT_STRIDE` slot per publication in rotation.
    records: MappedObject,
    /// Item-ring producer after each slot's last publication (its tag-16),
    /// or `None` for a slot never used.
    record_slot_end: [Option<u32>; crate::g17_queue_limits::COMPUTE_RECORD_SLOTS],
    /// Host-only cursor: item-ring slots below this (mod the ring count) have
    /// been zeroed since the firmware consumed them. Recycling is what makes
    /// submission depth unbounded -- see `recycle_consumed_ring_slots`.
    ring_reclaimed: u32,
    /// Slots reclaimed since boot. Counted rather than inferred from log lines,
    /// because a 400-deep run overflows the kernel ring buffer and makes any
    /// count taken by grepping dmesg an artefact of how much survived.
    ring_reclaimed_total: u64,
}

/// User-context aliases retained while one SKSM compute entry can still
/// execute. Firmware keeps the high descriptor and queue mappings; the GPU
/// consumes these aliases together with the userspace CDM and USC mappings.
#[cfg(not(test))]
pub(crate) struct G17PComputeUserMappings {
    descriptors: mmu::KernelMapping,
    preempt: mmu::KernelMapping,
    robustness: mmu::KernelMapping,
    operand_state: mmu::KernelMapping,
    queue_context: mmu::KernelMapping,
}

#[cfg(not(test))]
struct G17PComputeReadinessMappings {
    table: mmu::KernelMapping,
    buffers: KVec<mmu::KernelMapping>,
}

/// Queue-graph ring cursors and the first item-ring slots.
///
/// Every field is a plain read of DRAM the driver itself allocated. NOTHING
/// here touches sgx MMIO -- that distinction matters, because reading the
/// fault bank on a timeout path SErrors once the GPU cores have powered back
/// down, which is a hard panic rather than a diagnostic.
#[cfg(not(test))]
#[derive(Debug, Copy, Clone)]
pub(crate) struct G17PComputeRingState {
    pub(crate) queue: u64,
    /// Queue graph `+0x100`. `apply_g17p_initial_command_pointer` treats this
    /// as the firmware's consumer cursor; whether the firmware actually writes
    /// it is exactly what this diagnostic exists to settle.
    pub(crate) consumer: u32,
    /// Queue graph `+0x140`, the host's item-ring producer.
    pub(crate) producer: u32,
    /// Queue graph `+0x150`, initialised to `u32::MAX` by the graph builder.
    pub(crate) mirror: u32,
    /// Queue graph `+0x160`, the ring entry count (`0x500`).
    pub(crate) count: u32,
    pub(crate) items: [u64; 8],
    /// Host reclaim cursor, and slots reclaimed since boot.
    pub(crate) reclaimed: u32,
    pub(crate) reclaimed_total: u64,
}

